INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C1','kor',2,2,'u7',1,'생각을 표현하는 여러 상황 — 수업 시간 발표·모둠 대화·책을 읽고 짝과 이야기·칭찬 쪽지 붙이기처럼 일상에서 생각을 말이나 글로 나타내는 상황을 알고 경험 나누기',ARRAY['2국01-04']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C2','kor',2,2,'u7',1,'생각을 나타낼 때 내용과 태도 — 나타내려는 내용과 나타내는 태도(다른 생각 존중·끝까지 듣기)가 모두 중요함을 알기',ARRAY['2국01-04']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C3','kor',2,2,'u7',3,'제목으로 글쓴이의 생각 짐작하기 — 글쓴이는 제목에 생각을 담기도 하므로 제목을 보고 글쓴이가 하고 싶은 말을 짐작하기',ARRAY['2국02-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C4','kor',2,2,'u7',3,'중심 생각 찾기 — 작은 글마다 중심 생각을 찾고, 나머지 문장은 중심 생각을 설명하고 뒷받침하는 역할임을 알기',ARRAY['2국02-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C5','kor',2,2,'u7',3,'글쓴이의 생각 파악하기 — 제목과 여러 작은 글의 중심 생각을 모아 글 전체에서 드러나는 글쓴이의 생각을 정리하기(중심 생각 하나가 곧 글쓴이의 생각은 아님)',ARRAY['2국02-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C6','kor',2,2,'u7',5,'글의 내용 파악하기 — 「반려견을 사랑한다면」·「아침에 운동장을 달려요」에서 글쓴이가 든 까닭과 방법을 글에서 찾아 답하기',ARRAY['2국02-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C7','kor',2,2,'u7',5,'글쓴이의 생각에 대한 자신의 생각 — 경험이나 아는 것을 떠올려 글쓴이와 같거나 다른 생각을 까닭과 함께 정리하기(생각이 다른 것은 자연스러움, 설득이 목적이 아님)',ARRAY['2국01-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C8','kor',2,2,'u7',5,'바른 자세로 발표하고 듣기 — 친구들을 바라보며 또박또박 알맞은 목소리로 발표하고, 친구의 발표를 존중하며 귀 기울여 듣고 반응하기',ARRAY['2국01-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C9','kor',2,2,'u7',7,'생각을 나타내는 글의 내용 — 생각·생각에 대한 까닭·경험이나 알고 있는 것·느낌으로 글이 이루어짐을 알고, 생각을 나타내는 문장(~하자, ~는 어때?)을 가리기',ARRAY['2국03-04']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C10','kor',2,2,'u7',7,'자신의 생각을 글로 쓰기 — 글 쓸 상황과 읽을 사람을 정하고, 생각을 잘 나타내는 낱말과 예의 바른 표현으로 생각·까닭·경험·느낌 차례로 글 쓰기',ARRAY['2국03-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C11','kor',2,2,'u7',10,'친구 글에 댓글 쓰기 — 친구 글에서 생각을 파악하고, 읽을 친구의 마음을 생각하며 내 생각·궁금한 점·칭찬을 까닭과 함께 댓글로 쓰고 인상 깊은 댓글 발표하기',ARRAY['2국03-04']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C12','kor',2,2,'u7',11,'이야기 속 인물이 되어 생각 말하기 — 등장인물의 생각을 파악하고, 그 인물이 된다면 하고 싶은 말과 행동을 까닭과 함께 정리해 묻고 답하기',ARRAY['2국01-04']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u7-C13','kor',2,2,'u7',11,'글자와 소리가 다른 낱말 — 맑네[망네]·괜찮아[괜차나]·숲이[수피]처럼 겹받침·받침이 이웃 소리를 만나 글자와 다르게 소리 나는 낱말을 바르게 읽고 글자대로 쓰기(기초 다지기)',ARRAY['2국04-02']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X01','kor',2,'u7',ARRAY['K2-2-u7-C1','K2-2-u7-C2','K2-2-u7-C8']::text[],'생각을 나눌 때 다른 생각을 무시하거나 말을 끊는다','친구 말이 끝나면 「~라는 거지?」 하고 한 번 되짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X02','kor',2,'u7',ARRAY['K2-2-u7-C2']::text[],'생각을 나타낼 때 내용만 또는 태도만 중요하다고 여긴다','「무엇을」 + 「어떻게」 둘 다 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X03','kor',2,'u7',ARRAY['K2-2-u7-C3']::text[],'제목을 보지 않고 글쓴이의 생각을 짐작한다','읽기 전에 제목을 소리 내어 읽고 「무슨 말을 하고 싶을까?」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X04','kor',2,'u7',ARRAY['K2-2-u7-C4']::text[],'중심 생각 대신 예·까닭 같은 뒷받침 문장을 고른다','「첫째·둘째」 바로 뒤 문장, 나머지를 묶어 주는 문장 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X05','kor',2,'u7',ARRAY['K2-2-u7-C5']::text[],'중심 생각 하나를 글쓴이의 생각 전체로 여긴다','중심 생각을 모두 늘어놓고 제목과 함께 한 문장으로 묶기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X06','kor',2,'u7',ARRAY['K2-2-u7-C6','K2-2-u7-C12']::text[],'글에 없는 내용으로 답하거나 인물이 한 말을 바꿔 안다','「글 어디에 있지?」 하고 그 줄을 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X07','kor',2,'u7',ARRAY['K2-2-u7-C7']::text[],'글쓴이와 다른 생각은 틀린 것이라고 여기거나, 까닭 없이 좋다·싫다만 말한다','「나는 ~라고 생각해. 왜냐하면 ~」 틀로 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X08','kor',2,'u7',ARRAY['K2-2-u7-C8']::text[],'발표할 때 바닥을 보며 작게 말하거나, 들을 때 끼어들고 딴짓을 한다','말할 때 — 바라보기·또박또박 / 들을 때 — 귀 기울이기·고개 끄덕이기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X09','kor',2,'u7',ARRAY['K2-2-u7-C9']::text[],'생각만 쓰고 까닭을 빼거나, 생각·까닭·경험·느낌을 헷갈린다','「왜냐하면」 뒤는 까닭, 「~해 보았다」는 경험, 「~할 것 같다」는 느낌') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X10','kor',2,'u7',ARRAY['K2-2-u7-C10','K2-2-u7-C11']::text[],'읽을 사람을 생각하지 않고 탓하거나 짜증 내는 표현을 쓴다','「이 글을 읽는 친구 마음은?」 — 예의 바른 표현으로 바꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X11','kor',2,'u7',ARRAY['K2-2-u7-C11']::text[],'댓글을 「별로」처럼 막연하게 쓰거나 생각을 무시하는 말로 쓴다','공감·궁금한 점·칭찬 가운데 하나 + 까닭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X12','kor',2,'u7',ARRAY['K2-2-u7-C12','K2-2-u7-C7']::text[],'같은 장면에는 정답 생각이 하나뿐이라고 여긴다','「나라면?」 하고 친구와 다른 생각도 떠올려 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X13','kor',2,'u7',ARRAY['K2-2-u7-C9','K2-2-u7-C10']::text[],'생각을 나타내는 문장과 사실·상황을 알리는 문장을 헷갈린다','「~하자」, 「~는 어때?」, 「~합시다」면 생각') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X14','kor',2,'u7',ARRAY['K2-2-u7-C6','K2-2-u7-C7']::text[],'글의 문제 상황을 그 대상 전체에 대한 편견으로 받아들인다(반려견은 나쁘다)','글쓴이가 바라는 것은 「없애자」인지 「지키자」인지 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u7-X15','kor',2,'u7',ARRAY['K2-2-u7-C13']::text[],'소리 나는 대로 쓰거나 글자대로 읽어 소리와 글자를 헷갈린다','읽을 때는 [소리]대로, 쓸 때는 글자대로 — 둘을 나란히 적어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L01_basic#1','kor',2,2,'u7','L01','g2_2_kor_u7_L01_basic','lesson_basic','K2-2-u7-C1',1,'mc','auto','『국어』 199쪽 생각 열기 — 쥐들은 무엇을 하고 있나요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":1,"concept":"K2-2-u7-C1","difficulty":1,"kind":"mc","stem":"『국어』 199쪽 생각 열기 — 쥐들은 무엇을 하고 있나요?","options":[{"t":"고양이로부터 안전하게 지내려고 회의를 하고 있어요","correct":true},{"t":"치즈를 나누어 먹고 있어요","mis":"K2-2-u7-X06"},{"t":"모두 낮잠을 자고 있어요","mis":"K2-2-u7-X06"}],"explanation":["회의를 해요.","지도서 282쪽이에요.","생각을 나눠요."],"asset":{"type":"speech","turns":[{"who":"쥐 1","text":"누가 고양이 목에 방울을 달기만 하면 고양이 걱정 없이 지낼 수 있습니다!"},{"who":"쥐 2","text":"무슨 소리! 우리가 힘을 합쳐 고양이와 싸워야 합니다."},{"who":"쥐 3","text":"그러지 말고 평화롭게 고양이와 대화로 풀어 보는 것은 어떨까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L01_basic#2','kor',2,2,'u7','L01','g2_2_kor_u7_L01_basic','lesson_basic','K2-2-u7-C1',1,'mc','auto','수업 시간에 선생님께서 「민철이는 어떻게 생각하는지 발표해 보세요.」라고 하셨어요. 어떤 상황인가요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":2,"concept":"K2-2-u7-C1","difficulty":1,"kind":"mc","stem":"수업 시간에 선생님께서 「민철이는 어떻게 생각하는지 발표해 보세요.」라고 하셨어요. 어떤 상황인가요?","options":[{"t":"수업 시간에 자신의 생각을 발표하는 상황","correct":true},{"t":"친구 그림에 칭찬 쪽지를 붙이는 상황","mis":"K2-2-u7-X06"},{"t":"책을 읽고 짝과 이야기하는 상황","mis":"K2-2-u7-X06"}],"explanation":["발표 상황이에요.","201쪽 예시 답안이에요.","그림 ㉮예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
