INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L01_challenge#7','kor',2,2,'u7','L01','g2_2_kor_u7_L01_challenge','lesson_challenge','K2-2-u7-C1',3,'mc','auto','우리가 생각을 말이나 글로 나누는 곳으로 알맞은 것을 모두 담은 것은?',ARRAY['K2-2-u7-X02']::text[],false,'{"seq":7,"concept":"K2-2-u7-C1","difficulty":3,"kind":"mc","stem":"우리가 생각을 말이나 글로 나누는 곳으로 알맞은 것을 모두 담은 것은?","options":[{"t":"수업 시간·모둠 대화·짝과 책 이야기·친구 작품 칭찬","correct":true},{"t":"발표 시간에만","mis":"K2-2-u7-X02"},{"t":"글을 쓸 때만","mis":"K2-2-u7-X02"}],"explanation":["여러 곳이에요.","지도서 283쪽이에요.","일상 속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L01_challenge#8','kor',2,2,'u7','L01','g2_2_kor_u7_L01_challenge','lesson_challenge','K2-2-u7-C2',4,'sa','auto','생각을 말이나 글로 나타낼 때 중요한 두 가지는 「내용」과 「○○」예요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u7-C2","difficulty":4,"kind":"sa","stem":"생각을 말이나 글로 나타낼 때 중요한 두 가지는 「내용」과 「○○」예요. 빈칸 두 글자를 쓰세요.","answer":["태도"],"explanation":["태도예요.","지도서 281쪽이에요.","내용과 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L01_challenge#9','kor',2,2,'u7','L01','g2_2_kor_u7_L01_challenge','lesson_challenge','K2-2-u7-C1',4,'essay','teacher','『국어』 201쪽 3번 — 자신의 생각을 말이나 글로 나타냈던 경험을 「어떤 상황에서 / 어떤 생각을」 넣어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u7-C1","difficulty":4,"kind":"essay","stem":"『국어』 201쪽 3번 — 자신의 생각을 말이나 글로 나타냈던 경험을 「어떤 상황에서 / 어떤 생각을」 넣어 쓰세요.","answer_guide":{"answer":"예: 점심시간에 친구들과 놀이를 정할 때, 술래잡기를 하자고 내 생각을 말했다.","scoring_points":["상황을 썼어요","어떤 생각인지 썼어요"]},"explanation":["상황과 생각이에요.","201쪽 예시 답안이에요.","내 경험이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L01_challenge#10','kor',2,2,'u7','L01','g2_2_kor_u7_L01_challenge','lesson_challenge','K2-2-u7-C2',4,'essay','teacher','쥐들의 회의에서 내가 쥐라면 어떤 생각을 어떻게 말할지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C2","difficulty":4,"kind":"essay","stem":"쥐들의 회의에서 내가 쥐라면 어떤 생각을 어떻게 말할지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 다른 쥐들의 생각도 좋아요. 저는 고양이가 오는 시간을 서로 알려 주면 좋겠어요. 모두 함께 할 수 있는 방법이기 때문이에요.","scoring_points":["내 생각과 까닭이 있어요","다른 생각을 존중했어요"]},"explanation":["내용과 태도예요.","199쪽이에요.","배려해요."],"asset":{"type":"speech","turns":[{"who":"쥐 1","text":"누가 고양이 목에 방울을 달기만 하면 고양이 걱정 없이 지낼 수 있습니다!"},{"who":"쥐 2","text":"무슨 소리! 우리가 힘을 합쳐 고양이와 싸워야 합니다."},{"who":"쥐 3","text":"그러지 말고 평화롭게 고양이와 대화로 풀어 보는 것은 어떨까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#1','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C3',1,'mc','auto','「반려견을 사랑한다면」의 제목을 보고 짐작한 글쓴이의 말로 알맞은 것은?',ARRAY['K2-2-u7-X14','K2-2-u7-X03']::text[],false,'{"seq":1,"concept":"K2-2-u7-C3","difficulty":1,"kind":"mc","stem":"「반려견을 사랑한다면」의 제목을 보고 짐작한 글쓴이의 말로 알맞은 것은?","options":[{"t":"반려견을 키우는 사람들에게 에티켓을 지키자고 말하려는 것 같아요","correct":true},{"t":"반려견을 키우지 말자고 하려는 것 같아요","mis":"K2-2-u7-X14"},{"t":"반려견 이름 짓는 법을 알려 주려는 것 같아요","mis":"K2-2-u7-X03"}],"explanation":["에티켓이에요.","205쪽 예시 답안이에요.","제목을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#2','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C6',1,'mc','auto','글쓴이는 반려견의 배설물을 누가 치워야 한다고 했나요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":2,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"글쓴이는 반려견의 배설물을 누가 치워야 한다고 했나요?","options":[{"t":"반려견의 주인","correct":true},{"t":"지나가는 사람","mis":"K2-2-u7-X06"},{"t":"청소하는 분","mis":"K2-2-u7-X06"}],"explanation":["주인이에요.","지도서 286쪽이에요.","글 ㉯예요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#3','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C4',1,'mc','auto','글 ㉯의 중심 생각은?',ARRAY['K2-2-u7-X04']::text[],false,'{"seq":3,"concept":"K2-2-u7-C4","difficulty":1,"kind":"mc","stem":"글 ㉯의 중심 생각은?","options":[{"t":"반려견의 배설물은 주인이 치워야 한다.","correct":true},{"t":"반려견이 산책 중 변을 봤을 때 모르는 척 그냥 가 버리는 사람이 있다.","mis":"K2-2-u7-X04"},{"t":"그러면 그 자리에서 냄새가 나고 다른 사람이 배설물을 밟을 수도 있다.","mis":"K2-2-u7-X04"}],"explanation":["첫 문장이에요.","지도서 287쪽이에요.","나머지는 뒷받침해요."],"asset":{"type":"passage","lines":["반려견의 배설물은 주인이 치워야 한다.","반려견이 산책 중 변을 봤을 때 모르는 척 그냥 가 버리는 사람이 있다.","그러면 그 자리에서 냄새가 나고 다른 사람이 배설물을 밟을 수도 있다.","반려견과 산책할 때에는 비닐봉지와 집게 같은 도구를 챙겨야 한다."],"title":"「반려견을 사랑한다면」 글 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#4','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C6',1,'mc','auto','반려견의 짖는 소리가 다른 사람에게 피해를 줄 수 있는 곳으로 글에 나온 것은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":4,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"반려견의 짖는 소리가 다른 사람에게 피해를 줄 수 있는 곳으로 글에 나온 것은?","options":[{"t":"도서관","correct":true},{"t":"운동장","mis":"K2-2-u7-X06"},{"t":"공원","mis":"K2-2-u7-X06"}],"explanation":["도서관이에요.","지도서 286쪽이에요.","글 ㉱예요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#5','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C6',2,'mc','auto','글쓴이는 반려견을 야외로 데리고 나갈 때 왜 목줄을 채워야 한다고 했나요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":5,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"글쓴이는 반려견을 야외로 데리고 나갈 때 왜 목줄을 채워야 한다고 했나요?","options":[{"t":"개에게 물렸던 사람이나 개를 무서워하는 어린이는 개가 가까이 오는 것에 공포를 느끼기 때문에","correct":true},{"t":"목줄이 예뻐 보여서","mis":"K2-2-u7-X06"},{"t":"반려견이 목줄을 좋아해서","mis":"K2-2-u7-X06"}],"explanation":["공포를 느껴요.","204쪽 예시 답안이에요.","다른 사람을 생각해요."],"asset":{"type":"passage","lines":["반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","개에게 물렸던 사람이나 개를 무서워하는 어린이는 공포를 느낄 수 있다.","반려견을 목줄 없이 풀어놓는 것은 이들에게 위협적인 행동이 될 수 있다."],"title":"「반려견을 사랑한다면」 글 ㉰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#6','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C6',2,'mc','auto','글쓴이는 반려견을 진심으로 사랑한다면 어떻게 해야 한다고 했나요?',ARRAY['K2-2-u7-X14','K2-2-u7-X06']::text[],false,'{"seq":6,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"글쓴이는 반려견을 진심으로 사랑한다면 어떻게 해야 한다고 했나요?","options":[{"t":"반려견이 미움을 받거나 공포의 대상이 되지 않도록 해야 해요","correct":true},{"t":"반려견을 집 밖에 절대 데리고 나가지 않아요","mis":"K2-2-u7-X14"},{"t":"반려견이 하고 싶은 대로 다 하게 해요","mis":"K2-2-u7-X06"}],"explanation":["책임이에요.","204쪽 예시 답안이에요.","글 ㉲예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#7','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C4',2,'match','auto','글과 중심 생각을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K2-2-u7-C4","difficulty":2,"kind":"match","stem":"글과 중심 생각을 이어 보세요.","pairs":[{"l":"글 ㉰","r":"반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다."},{"l":"글 ㉱","r":"반려견의 출입이 금지된 곳에는 반려견을 데리고 가지 않아야 한다."},{"l":"글 ㉲","r":"다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."}],"mis":"K2-2-u7-X04","explanation":["작은 글마다 하나씩이에요.","205쪽 예시 답안이에요.","중심 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_basic#8','kor',2,2,'u7','L03','g2_2_kor_u7_L03_basic','lesson_basic','K2-2-u7-C5',2,'mc','auto','「반려견을 사랑한다면」에서 글쓴이의 생각은?',ARRAY['K2-2-u7-X05','K2-2-u7-X14']::text[],false,'{"seq":8,"concept":"K2-2-u7-C5","difficulty":2,"kind":"mc","stem":"「반려견을 사랑한다면」에서 글쓴이의 생각은?","options":[{"t":"반려견을 진심으로 사랑한다면 여러 가지 반려견 에티켓을 꼭 지켜야 한다","correct":true},{"t":"반려견의 배설물은 주인이 치워야 한다","mis":"K2-2-u7-X05"},{"t":"반려견은 무서운 동물이다","mis":"K2-2-u7-X14"}],"explanation":["모아서 정리해요.","206쪽 예시 답안이에요.","중심 생각 하나가 아니에요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
