INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_challenge#6','kor',2,2,'u7','L03','g2_2_kor_u7_L03_challenge','lesson_challenge','K2-2-u7-C3',3,'mc','auto','「왜 공공장소에서 질서를 지켜야 할까요?」라는 제목의 글에서 글쓴이의 생각으로 알맞은 것은?',ARRAY['K2-2-u7-X03']::text[],false,'{"seq":6,"concept":"K2-2-u7-C3","difficulty":3,"kind":"mc","stem":"「왜 공공장소에서 질서를 지켜야 할까요?」라는 제목의 글에서 글쓴이의 생각으로 알맞은 것은?","options":[{"t":"공공장소에서 질서를 지키자","correct":true},{"t":"공공장소에 가지 말자","mis":"K2-2-u7-X03"},{"t":"급식을 먼저 먹자","mis":"K2-2-u7-X03"}],"explanation":["질서를 지키자예요.","지도서 287쪽 참고 자료예요.","제목에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_challenge#7','kor',2,2,'u7','L03','g2_2_kor_u7_L03_challenge','lesson_challenge','K2-2-u7-C5',3,'mc','auto','「외출하고 돌아온 뒤에는 손을 꼭 씻자」에서 글쓴이의 생각은?',ARRAY['K2-2-u7-X05']::text[],false,'{"seq":7,"concept":"K2-2-u7-C5","difficulty":3,"kind":"mc","stem":"「외출하고 돌아온 뒤에는 손을 꼭 씻자」에서 글쓴이의 생각은?","options":[{"t":"외출하고 돌아온 뒤에는 손을 꼭 씻자","correct":true},{"t":"손에는 세균이 많다","mis":"K2-2-u7-X05"},{"t":"가족과 물건을 같이 쓴다","mis":"K2-2-u7-X05"}],"explanation":["제목에 있어요.","지도서 311쪽이에요.","중심 생각을 모아요."],"asset":{"type":"passage","lines":["㉮ 자신의 건강을 위해 외출하고 돌아온 뒤에는 손을 꼭 씻어야 해요.","여러 물건을 만지는 사이에 손에 세균이 달라붙었기 때문이에요.","㉯ 그리고 외출 뒤 손 씻기는 가족의 건강을 생각하는 행동이에요.","씻지 않은 손으로 같이 쓰는 물건을 만지면 세균이 옮겨 붙을 수 있어요."],"title":"지도서 311쪽 평가 「외출하고 돌아온 뒤에는 손을 꼭 씻자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_challenge#8','kor',2,2,'u7','L03','g2_2_kor_u7_L03_challenge','lesson_challenge','K2-2-u7-C3',4,'sa','auto','글쓴이의 생각을 파악하려면 글의 ○○을 반드시 확인해야 해요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u7-C3","difficulty":4,"kind":"sa","stem":"글쓴이의 생각을 파악하려면 글의 ○○을 반드시 확인해야 해요. 빈칸 두 글자를 쓰세요.","answer":["제목"],"explanation":["제목이에요.","지도서 287쪽이에요.","생각을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_challenge#9','kor',2,2,'u7','L03','g2_2_kor_u7_L03_challenge','lesson_challenge','K2-2-u7-C5',4,'essay','teacher','「반려견을 사랑한다면」의 제목과 글 ㉯~㉲의 중심 생각을 모아 글쓴이의 생각을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u7-C5","difficulty":4,"kind":"essay","stem":"「반려견을 사랑한다면」의 제목과 글 ㉯~㉲의 중심 생각을 모아 글쓴이의 생각을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 다른 사람과 내 반려견을 위해 반려견 에티켓을 꼭 지키자.","scoring_points":["여러 중심 생각을 모았어요","한 문장으로 썼어요"]},"explanation":["모아서 한 문장이에요.","206쪽이에요.","글쓴이의 생각이에요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L03_challenge#10','kor',2,2,'u7','L03','g2_2_kor_u7_L03_challenge','lesson_challenge','K2-2-u7-C5',4,'essay','teacher','『국어』 206쪽 5번 — 글쓴이의 생각을 파악하며 글을 읽으면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C5","difficulty":4,"kind":"essay","stem":"『국어』 206쪽 5번 — 글쓴이의 생각을 파악하며 글을 읽으면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 글쓴이가 글을 통해 하고 싶은 말이 무엇인지 알 수 있고, 내 생각과 견주며 읽을 수 있다.","scoring_points":["좋은 점을 썼어요","글쓴이의 생각과 이었어요"]},"explanation":["좋은 점이에요.","206쪽 예시 답안이에요.","집중해서 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L05_basic#1','kor',2,2,'u7','L05','g2_2_kor_u7_L05_basic','lesson_basic','K2-2-u7-C6',1,'mc','auto','「아침에 운동장을 달려요」를 쓴 사람은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":1,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"「아침에 운동장을 달려요」를 쓴 사람은?","options":[{"t":"2학년 3반 이채영","correct":true},{"t":"2학년 3반 규빈","mis":"K2-2-u7-X06"},{"t":"선생님","mis":"K2-2-u7-X06"}],"explanation":["이채영이에요.","207쪽이에요.","글 ㉮예요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
