INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L05_basic#5','kor',2,2,'u7','L05','g2_2_kor_u7_L05_basic','lesson_basic','K2-2-u7-C6',2,'mc','auto','글쓴이는 아침에 운동장을 달리면 왜 기분이 좋아진다고 했나요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":5,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"글쓴이는 아침에 운동장을 달리면 왜 기분이 좋아진다고 했나요?","options":[{"t":"운동장에 가득한 시원한 공기가 스트레스를 사라지게 하기 때문에","correct":true},{"t":"달리기 대회에서 상을 받아서","mis":"K2-2-u7-X06"},{"t":"간식을 주기 때문에","mis":"K2-2-u7-X06"}],"explanation":["시원한 공기예요.","208쪽 예시 답안이에요.","글 ㉯예요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
