INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L05_challenge#8','kor',2,2,'u7','L05','g2_2_kor_u7_L05_challenge','lesson_challenge','K2-2-u7-C5',4,'sa','auto','「아침에 운동장을 달려요」에서 글쓴이의 생각을 「~자.」로 끝나게 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u7-C5","difficulty":4,"kind":"sa","stem":"「아침에 운동장을 달려요」에서 글쓴이의 생각을 「~자.」로 끝나게 쓰세요.","answer":["아침에 운동장을 달리자.","아침에 운동장을 달리자","아침에 다 같이 운동장을 달리자."],"explanation":["달리자예요.","209쪽 예시 답안이에요.","~자로 끝나요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L05_challenge#9','kor',2,2,'u7','L05','g2_2_kor_u7_L05_challenge','lesson_challenge','K2-2-u7-C7',4,'essay','teacher','『국어』 209쪽 — 글쓴이의 생각에 대한 자신의 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u7-C7","difficulty":4,"kind":"essay","stem":"『국어』 209쪽 — 글쓴이의 생각에 대한 자신의 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 아침에 운동장을 달리면 좋은 점이 많다고 하니 나도 아침에 운동장을 달려야겠다. 나도 달리고 나면 기분이 좋았기 때문이다.","scoring_points":["글쓴이의 생각을 말했어요","내 생각과 까닭이 있어요"]},"explanation":["까닭과 함께요.","209쪽 예시 답안이에요.","같거나 달라도 돼요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L05_challenge#10','kor',2,2,'u7','L05','g2_2_kor_u7_L05_challenge','lesson_challenge','K2-2-u7-C8',4,'essay','teacher','발표하는 사람과 듣는 사람이 지킬 태도를 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C8","difficulty":4,"kind":"essay","stem":"발표하는 사람과 듣는 사람이 지킬 태도를 하나씩 쓰세요.","answer_guide":{"answer":"예: 발표하는 사람은 친구들을 바라보며 또박또박 말한다. 듣는 사람은 친구의 발표를 존중하며 귀 기울여 듣는다.","scoring_points":["발표하는 태도를 썼어요","듣는 태도를 썼어요"]},"explanation":["둘 다예요.","210쪽이에요.","바른 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#1','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C6',1,'mc','auto','「왜 책임이 필요하죠?」에서 등장인물들은 무엇을 정하려고 생각을 나누나요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":1,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"「왜 책임이 필요하죠?」에서 등장인물들은 무엇을 정하려고 생각을 나누나요?","options":[{"t":"학교 뒤뜰에 무엇을 키울지","correct":true},{"t":"소풍 갈 장소","mis":"K2-2-u7-X06"},{"t":"교실 벽 색깔","mis":"K2-2-u7-X06"}],"explanation":["뒤뜰 꾸미기예요.","215쪽 예시 답안이에요.","생각을 나눠요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#2','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C12',1,'mc','auto','「병아리 키워요. 달걀 먹을 수 있잖아요.」라고 말한 인물은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":2,"concept":"K2-2-u7-C12","difficulty":1,"kind":"mc","stem":"「병아리 키워요. 달걀 먹을 수 있잖아요.」라고 말한 인물은?","options":[{"t":"우철","correct":true},{"t":"규빈","mis":"K2-2-u7-X06"},{"t":"선생님","mis":"K2-2-u7-X06"}],"explanation":["우철이에요.","215쪽 예시 답안이에요.","인물과 생각이에요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#3','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C9',1,'mc','auto','「왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.」는 무엇에 해당하나요?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":3,"concept":"K2-2-u7-C9","difficulty":1,"kind":"mc","stem":"「왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.」는 무엇에 해당하나요?","options":[{"t":"생각에 대한 까닭","correct":true},{"t":"느낌","mis":"K2-2-u7-X09"},{"t":"경험이나 알고 있는 것","mis":"K2-2-u7-X09"}],"explanation":["까닭이에요.","216쪽 예시 답안이에요.","왜냐하면이에요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#4','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C9',1,'mc','auto','규빈이 글에서 「생각」에 해당하는 문장은?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":4,"concept":"K2-2-u7-C9","difficulty":1,"kind":"mc","stem":"규빈이 글에서 「생각」에 해당하는 문장은?","options":[{"t":"뒤뜰에서 병아리를 키웁시다.","correct":true},{"t":"정말 뿌듯할 것 같습니다.","mis":"K2-2-u7-X09"},{"t":"책에서 보았습니다.","mis":"K2-2-u7-X09"}],"explanation":["키웁시다예요.","216쪽 예시 답안이에요.","~합시다예요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#5','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C6',2,'mc','auto','규빈이가 병아리를 키우자고 한 까닭은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":5,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"규빈이가 병아리를 키우자고 한 까닭은?","options":[{"t":"병아리가 자라며 닭이 되는 과정을 볼 수 있기 때문에","correct":true},{"t":"달걀을 먹을 수 있기 때문에","mis":"K2-2-u7-X06"},{"t":"강아지보다 작아서","mis":"K2-2-u7-X06"}],"explanation":["닭이 되는 과정이에요.","215쪽 예시 답안이에요.","규빈이 말이에요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#6','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C6',2,'mc','auto','동물이나 식물을 키울 때 책임이 필요한 까닭은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":6,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"동물이나 식물을 키울 때 책임이 필요한 까닭은?","options":[{"t":"동물과 식물은 소중한 생명이기 때문에","correct":true},{"t":"돈을 벌 수 있어서","mis":"K2-2-u7-X06"},{"t":"선생님이 혼내셔서","mis":"K2-2-u7-X06"}],"explanation":["생명이에요.","215쪽 예시 답안이에요.","돌봐야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#7','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C9',2,'match','auto','규빈이 글의 문장과 역할을 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K2-2-u7-C9","difficulty":2,"kind":"match","stem":"규빈이 글의 문장과 역할을 이어 보세요.","pairs":[{"l":"뒤뜰에서 병아리를 키웁시다.","r":"생각"},{"l":"책임감을 기를 수 있기 때문입니다.","r":"생각에 대한 까닭"},{"l":"책에서 보았습니다.","r":"경험이나 알고 있는 것"},{"l":"정말 뿌듯할 것 같습니다.","r":"느낌"}],"mis":"K2-2-u7-X09","explanation":["네 가지예요.","216쪽 예시 답안이에요.","생각을 나타내는 글이에요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#8','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C12',2,'mc','auto','인물과 생각을 바르게 짝 지은 것은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":8,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"인물과 생각을 바르게 짝 지은 것은?","options":[{"t":"선생님 — 병아리를 키우는 것은 좋지만 책임지고 보살필 사람이 필요해요","correct":true},{"t":"규빈 — 달걀을 먹을 수 있잖아요","mis":"K2-2-u7-X06"},{"t":"우철 — 돌보미를 정하면 돼요","mis":"K2-2-u7-X06"}],"explanation":["선생님 생각이에요.","215쪽 예시 답안이에요.","인물마다 달라요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#9','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C10',2,'mc','auto','생각을 글로 나타낼 때 알맞은 표현은?',ARRAY['K2-2-u7-X10','K2-2-u7-X09']::text[],false,'{"seq":9,"concept":"K2-2-u7-C10","difficulty":2,"kind":"mc","stem":"생각을 글로 나타낼 때 알맞은 표현은?","options":[{"t":"「~합시다. 왜냐하면 ~때문입니다.」처럼 예의 바르게 써요","correct":true},{"t":"「~해! 너희가 안 하니까 짜증 나.」처럼 써요","mis":"K2-2-u7-X10"},{"t":"까닭은 빼고 생각만 써요","mis":"K2-2-u7-X09"}],"explanation":["예의 바르게요.","216쪽 도움말이에요.","읽는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_basic#10','kor',2,2,'u7','L07','g2_2_kor_u7_L07_basic','lesson_basic','K2-2-u7-C9',3,'mc','auto','생각에 대한 까닭을 함께 쓰면 좋은 점은?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":10,"concept":"K2-2-u7-C9","difficulty":3,"kind":"mc","stem":"생각에 대한 까닭을 함께 쓰면 좋은 점은?","options":[{"t":"읽는 사람이 내 생각을 이해하고 받아들이는 데 도움이 돼요","correct":true},{"t":"글자 수가 많아져요","mis":"K2-2-u7-X09"},{"t":"까닭은 없어도 돼요","mis":"K2-2-u7-X09"}],"explanation":["설득에 도움이 돼요.","215쪽 도움말이에요.","까닭이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
