INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_challenge#3','kor',2,2,'u7','L07','g2_2_kor_u7_L07_challenge','lesson_challenge','K2-2-u7-C10',3,'ox','auto','생각을 나타내는 글은 나만 이해할 수 있게 쓰면 된다.',ARRAY['K2-2-u7-X10']::text[],false,'{"seq":3,"concept":"K2-2-u7-C10","difficulty":3,"kind":"ox","stem":"생각을 나타내는 글은 나만 이해할 수 있게 쓰면 된다.","answer":"X","reason_options":[{"t":"글을 읽을 사람을 생각해 알아보기 쉽게 써야 해서","correct":true},{"t":"내 글이니까 나만 알면 돼서","mis":"K2-2-u7-X10"}],"mis":"K2-2-u7-X10","explanation":["읽을 사람을 생각해요.","국어활동 97쪽이에요.","함께 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
