INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_challenge#5','kor',2,2,'u7','L07','g2_2_kor_u7_L07_challenge','lesson_challenge','K2-2-u7-C10',3,'mc','auto','『국어활동』 96쪽 — 상대를 존중하며 생각을 바르게 나타낸 친구는?',ARRAY['K2-2-u7-X10']::text[],false,'{"seq":5,"concept":"K2-2-u7-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 96쪽 — 상대를 존중하며 생각을 바르게 나타낸 친구는?","options":[{"t":"「「문을 잘 닫고 다니자」는 규칙을 만듭시다. 문 앞에 앉은 학생이 매번 문을 닫아야 해서 불편할 수 있기 때문입니다.」","correct":true},{"t":"「너희가 문을 잘 안 닫아서 매번 내가 닫잖아.」","mis":"K2-2-u7-X10"},{"t":"「문을 안 닫는 친구들 때문에 짜증이 나기 때문입니다.」","mis":"K2-2-u7-X10"}],"explanation":["존중하는 표현이에요.","국어활동 96쪽 예시 답안이에요.","효은이 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_challenge#6','kor',2,2,'u7','L07','g2_2_kor_u7_L07_challenge','lesson_challenge','K2-2-u7-C13',3,'mc','auto','다음 가운데 생각을 나타내는 문장은?',ARRAY['K2-2-u7-X13']::text[],false,'{"seq":6,"concept":"K2-2-u7-C13","difficulty":3,"kind":"mc","stem":"다음 가운데 생각을 나타내는 문장은?","options":[{"t":"놀이할 때 규칙을 지키자.","correct":true},{"t":"지금 다섯 시야.","mis":"K2-2-u7-X13"},{"t":"이 아이스크림은 오백 원이야.","mis":"K2-2-u7-X13"}],"explanation":["지키자예요.","225쪽 예시 답안이에요.","~하자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_challenge#7','kor',2,2,'u7','L07','g2_2_kor_u7_L07_challenge','lesson_challenge','K2-2-u7-C10',3,'mc','auto','생각을 글로 쓰기 전에 먼저 정할 것은?',ARRAY['K2-2-u7-X10']::text[],false,'{"seq":7,"concept":"K2-2-u7-C10","difficulty":3,"kind":"mc","stem":"생각을 글로 쓰기 전에 먼저 정할 것은?","options":[{"t":"글을 쓸 상황과 읽을 사람","correct":true},{"t":"글씨 색깔","mis":"K2-2-u7-X10"},{"t":"종이 크기","mis":"K2-2-u7-X10"}],"explanation":["상황과 읽을 사람이에요.","217쪽이에요.","쓸 준비예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_challenge#8','kor',2,2,'u7','L07','g2_2_kor_u7_L07_challenge','lesson_challenge','K2-2-u7-C9',4,'sa','auto','생각을 나타내는 글에 들어가는 네 가지는 생각, 생각에 대한 까닭, 경험이나 알고 있는 것, 그리고 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u7-C9","difficulty":4,"kind":"sa","stem":"생각을 나타내는 글에 들어가는 네 가지는 생각, 생각에 대한 까닭, 경험이나 알고 있는 것, 그리고 무엇인가요? 두 글자로 쓰세요.","answer":["느낌"],"explanation":["느낌이에요.","216쪽이에요.","네 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_challenge#9','kor',2,2,'u7','L07','g2_2_kor_u7_L07_challenge','lesson_challenge','K2-2-u7-C10',4,'essay','teacher','『국어』 219쪽 8번 — 자신의 생각을 생각·까닭·경험이나 알고 있는 것·느낌을 넣어 글로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u7-C10","difficulty":4,"kind":"essay","stem":"『국어』 219쪽 8번 — 자신의 생각을 생각·까닭·경험이나 알고 있는 것·느낌을 넣어 글로 쓰세요.","answer_guide":{"answer":"예: 우리 반에서 책 바꿔 읽기 행사를 합시다. 왜냐하면 친구들이 좋아하는 책을 알 수 있기 때문입니다. 지난번에 친구가 빌려준 책이 정말 재미있었습니다. 행사를 하면 모두 즐거울 것 같습니다.","scoring_points":["생각과 까닭이 있어요","경험과 느낌이 있어요","예의 바른 표현이에요"]},"explanation":["네 가지를 넣어요.","219쪽이에요.","읽을 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L07_challenge#10','kor',2,2,'u7','L07','g2_2_kor_u7_L07_challenge','lesson_challenge','K2-2-u7-C9',4,'essay','teacher','『국어활동』 98쪽 — 계단에서 뛰는 친구들을 보고 자신의 생각을 표현하는 글을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C9","difficulty":4,"kind":"essay","stem":"『국어활동』 98쪽 — 계단에서 뛰는 친구들을 보고 자신의 생각을 표현하는 글을 쓰세요.","answer_guide":{"answer":"예: 학교 계단에서는 걸어 다녀야 합니다. 급하게 뛰다가 다른 친구와 부딪칠 수 있기 때문입니다. 저도 계단에서 뛰다가 다칠 뻔한 적이 있습니다. 모두 안전하게 계단을 이용하면 좋겠습니다.","scoring_points":["생각과 까닭이 있어요","경험이나 느낌이 있어요"]},"explanation":["생각을 나타내요.","국어활동 98쪽 예시 답안이에요.","안전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_basic#1','kor',2,2,'u7','L10','g2_2_kor_u7_L10_basic','lesson_basic','K2-2-u7-C11',1,'mc','auto','봄솔이가 읽고 웃게 될 댓글은?',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":1,"concept":"K2-2-u7-C11","difficulty":1,"kind":"mc","stem":"봄솔이가 읽고 웃게 될 댓글은?","options":[{"t":"댓글 ㉠","correct":true},{"t":"댓글 ㉡","mis":"K2-2-u7-X11"},{"t":"둘 다 아니에요","mis":"K2-2-u7-X11"}],"explanation":["㉠이에요.","지도서 300쪽이에요.","공감해요."],"asset":{"type":"passage","lines":["봄솔이의 글: 쉬는 시간에 복도에서 뛰지 맙시다.","왜냐하면 친구와 부딪쳐 다칠 수 있기 때문입니다.","댓글 ㉠: 좋은 생각이야! 나도 지난주에 복도에서 부딪칠 뻔했어.","댓글 ㉡: 그걸 누가 몰라? 재미없어."],"title":"친구 글과 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
