INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_basic#5','kor',2,2,'u7','L10','g2_2_kor_u7_L10_basic','lesson_basic','K2-2-u7-C11',2,'mc','auto','봄솔이 글에 바르게 쓴 댓글은?',ARRAY['K2-2-u7-X11','K2-2-u7-X10']::text[],false,'{"seq":5,"concept":"K2-2-u7-C11","difficulty":2,"kind":"mc","stem":"봄솔이 글에 바르게 쓴 댓글은?","options":[{"t":"「나도 같은 생각이야. 복도에서 뛰면 위험하니까.」","correct":true},{"t":"「별로야.」","mis":"K2-2-u7-X11"},{"t":"「너도 맨날 뛰잖아.」","mis":"K2-2-u7-X10"}],"explanation":["까닭과 함께요.","221쪽이에요.","공감해요."],"asset":{"type":"passage","lines":["봄솔이의 글: 쉬는 시간에 복도에서 뛰지 맙시다.","왜냐하면 친구와 부딪쳐 다칠 수 있기 때문입니다.","댓글 ㉠: 좋은 생각이야! 나도 지난주에 복도에서 부딪칠 뻔했어.","댓글 ㉡: 그걸 누가 몰라? 재미없어."],"title":"친구 글과 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_basic#6','kor',2,2,'u7','L10','g2_2_kor_u7_L10_basic','lesson_basic','K2-2-u7-C11',2,'mc','auto','친구 글에 궁금한 점을 묻는 댓글로 알맞은 것은?',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":6,"concept":"K2-2-u7-C11","difficulty":2,"kind":"mc","stem":"친구 글에 궁금한 점을 묻는 댓글로 알맞은 것은?","options":[{"t":"「좋은 생각이야. 그런데 계단에서는 어떻게 하면 좋을까?」","correct":true},{"t":"「그걸 누가 몰라?」","mis":"K2-2-u7-X11"},{"t":"「재미없어.」","mis":"K2-2-u7-X11"}],"explanation":["궁금한 점이에요.","220쪽 도움말이에요.","물어볼 수 있어요."],"asset":{"type":"passage","lines":["봄솔이의 글: 쉬는 시간에 복도에서 뛰지 맙시다.","왜냐하면 친구와 부딪쳐 다칠 수 있기 때문입니다.","댓글 ㉠: 좋은 생각이야! 나도 지난주에 복도에서 부딪칠 뻔했어.","댓글 ㉡: 그걸 누가 몰라? 재미없어."],"title":"친구 글과 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
