INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_challenge#3','kor',2,2,'u7','L10','g2_2_kor_u7_L10_challenge','lesson_challenge','K2-2-u7-C11',3,'ox','auto','친구 글이 마음에 들지 않으면 「별로야.」라고만 써도 된다.',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":3,"concept":"K2-2-u7-C11","difficulty":3,"kind":"ox","stem":"친구 글이 마음에 들지 않으면 「별로야.」라고만 써도 된다.","answer":"X","reason_options":[{"t":"까닭 없이 짧게 쓰면 친구가 속상하고 생각이 전해지지 않아서","correct":true},{"t":"솔직한 게 제일 좋아서","mis":"K2-2-u7-X11"}],"mis":"K2-2-u7-X11","explanation":["까닭과 배려예요.","지도서 300쪽이에요.","바른 댓글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
