INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_challenge#5','kor',2,2,'u7','L10','g2_2_kor_u7_L10_challenge','lesson_challenge','K2-2-u7-C11',3,'mc','auto','칭찬하는 댓글로 가장 알맞은 것은?',ARRAY['K2-2-u7-X11','K2-2-u7-X10']::text[],false,'{"seq":5,"concept":"K2-2-u7-C11","difficulty":3,"kind":"mc","stem":"칭찬하는 댓글로 가장 알맞은 것은?","options":[{"t":"「까닭이 분명해서 네 생각이 잘 이해돼.」","correct":true},{"t":"「잘했네.」","mis":"K2-2-u7-X11"},{"t":"「내 글이 더 좋아.」","mis":"K2-2-u7-X10"}],"explanation":["구체적인 칭찬이에요.","지도서 301쪽이에요.","무엇이 좋은지요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_challenge#6','kor',2,2,'u7','L10','g2_2_kor_u7_L10_challenge','lesson_challenge','K2-2-u7-C11',3,'mc','auto','친구 글에 대한 내 생각을 쓰려면 먼저 해야 할 일은?',ARRAY['K2-2-u7-X06','K2-2-u7-X11']::text[],false,'{"seq":6,"concept":"K2-2-u7-C11","difficulty":3,"kind":"mc","stem":"친구 글에 대한 내 생각을 쓰려면 먼저 해야 할 일은?","options":[{"t":"친구 글에서 친구의 생각을 파악해요","correct":true},{"t":"친구 이름만 확인해요","mis":"K2-2-u7-X06"},{"t":"붙임쪽지를 먼저 붙여요","mis":"K2-2-u7-X11"}],"explanation":["생각을 파악해요.","지도서 301쪽이에요.","배운 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_challenge#7','kor',2,2,'u7','L10','g2_2_kor_u7_L10_challenge','lesson_challenge','K2-2-u7-C10',3,'mc','auto','『국어활동』 96쪽 — 상대를 배려하고 존중하는 표현이 아닌 것은?',ARRAY['K2-2-u7-X10']::text[],false,'{"seq":7,"concept":"K2-2-u7-C10","difficulty":3,"kind":"mc","stem":"『국어활동』 96쪽 — 상대를 배려하고 존중하는 표현이 아닌 것은?","options":[{"t":"「너희가 문을 잘 안 닫고 다녀서 매번 문 앞에 앉은 친구가 닫아야 하잖아.」","correct":true},{"t":"「문을 잘 닫고 다니자는 학급 규칙을 만듭시다.」","mis":"K2-2-u7-X10"},{"t":"「불편할 수 있기 때문입니다.」","mis":"K2-2-u7-X10"}],"explanation":["탓하는 표현이에요.","국어활동 96쪽이에요.","존중하는 말로요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_challenge#8','kor',2,2,'u7','L10','g2_2_kor_u7_L10_challenge','lesson_challenge','K2-2-u7-C11',4,'sa','auto','친구가 쓴 글 아래에 다는 짧은 글을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u7-C11","difficulty":4,"kind":"sa","stem":"친구가 쓴 글 아래에 다는 짧은 글을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["댓글"],"explanation":["댓글이에요.","220쪽이에요.","붙임쪽지에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_challenge#9','kor',2,2,'u7','L10','g2_2_kor_u7_L10_challenge','lesson_challenge','K2-2-u7-C11',4,'essay','teacher','봄솔이의 글에 달 댓글을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u7-C11","difficulty":4,"kind":"essay","stem":"봄솔이의 글에 달 댓글을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 좋은 생각이야. 복도에서 뛰면 모퉁이에서 부딪칠 수 있으니까 나도 걸어 다닐게.","scoring_points":["봄솔이의 생각에 대한 내 생각이에요","까닭이 있어요","고운 말이에요"]},"explanation":["까닭과 함께요.","221쪽이에요.","배려해요."],"asset":{"type":"passage","lines":["봄솔이의 글: 쉬는 시간에 복도에서 뛰지 맙시다.","왜냐하면 친구와 부딪쳐 다칠 수 있기 때문입니다.","댓글 ㉠: 좋은 생각이야! 나도 지난주에 복도에서 부딪칠 뻔했어.","댓글 ㉡: 그걸 누가 몰라? 재미없어."],"title":"친구 글과 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L10_challenge#10','kor',2,2,'u7','L10','g2_2_kor_u7_L10_challenge','lesson_challenge','K2-2-u7-C11',4,'essay','teacher','내 글에 달린 댓글 가운데 가장 인상 깊은 댓글을 하나 정해 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C11","difficulty":4,"kind":"essay","stem":"내 글에 달린 댓글 가운데 가장 인상 깊은 댓글을 하나 정해 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「나도 그런 적 있어.」라는 댓글이 가장 인상 깊었다. 내 생각에 공감해 주어서 힘이 났기 때문이다.","scoring_points":["댓글을 하나 골랐어요","까닭을 썼어요"]},"explanation":["까닭과 함께요.","221쪽 (2)예요.","발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_basic#1','kor',2,2,'u7','L11','g2_2_kor_u7_L11_basic','lesson_basic','K2-2-u7-C12',1,'mc','auto','『국어』 222쪽 — 이야기 속 인물이 되어 생각하기에서 가장 먼저 할 일은?',ARRAY['K2-2-u7-X12']::text[],false,'{"seq":1,"concept":"K2-2-u7-C12","difficulty":1,"kind":"mc","stem":"『국어』 222쪽 — 이야기 속 인물이 되어 생각하기에서 가장 먼저 할 일은?","options":[{"t":"활동을 위한 이야기 선정하기","correct":true},{"t":"등장인물의 의자에 앉기","mis":"K2-2-u7-X12"},{"t":"되고 싶은 인물 고르기","mis":"K2-2-u7-X12"}],"explanation":["이야기 고르기예요.","222쪽이에요.","①이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
