INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_basic#5','kor',2,2,'u7','L11','g2_2_kor_u7_L11_basic','lesson_basic','K2-2-u7-C12',2,'mc','auto','활동할 이야기를 고를 때 알맞은 것은?',ARRAY['K2-2-u7-X12']::text[],false,'{"seq":5,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"활동할 이야기를 고를 때 알맞은 것은?","options":[{"t":"등장인물의 생각이 분명히 드러나는 대사나 장면이 많은 이야기","correct":true},{"t":"글자가 가장 많은 이야기","mis":"K2-2-u7-X12"},{"t":"그림이 하나도 없는 이야기","mis":"K2-2-u7-X12"}],"explanation":["생각이 드러나요.","지도서 302쪽이에요.","인물이 되어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_basic#6','kor',2,2,'u7','L11','g2_2_kor_u7_L11_basic','lesson_basic','K2-2-u7-C12',2,'mc','auto','「선생님, 제가 하겠습니다!」 「그럼 돌아가면서 돌볼게요.」에서 규빈이의 생각은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":6,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"「선생님, 제가 하겠습니다!」 「그럼 돌아가면서 돌볼게요.」에서 규빈이의 생각은?","options":[{"t":"돌보미를 정해 병아리를 돌아가며 책임지고 돌보자","correct":true},{"t":"병아리를 키워 달걀을 먹자","mis":"K2-2-u7-X06"},{"t":"병아리는 키우지 말자","mis":"K2-2-u7-X06"}],"explanation":["함께 돌보자예요.","214쪽이에요.","규빈이 말이에요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_basic#7','kor',2,2,'u7','L11','g2_2_kor_u7_L11_basic','lesson_basic','K2-2-u7-C12',2,'mc','auto','인물 의자에 앉은 「규빈」에게 할 질문으로 알맞은 것은?',ARRAY['K2-2-u7-X10','K2-2-u7-X12']::text[],false,'{"seq":7,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"인물 의자에 앉은 「규빈」에게 할 질문으로 알맞은 것은?","options":[{"t":"「규빈아, 병아리를 키우자고 한 까닭은 무엇이니?」","correct":true},{"t":"「너는 왜 그렇게 이상하니?」","mis":"K2-2-u7-X10"},{"t":"「아무거나 말해 봐.」","mis":"K2-2-u7-X12"}],"explanation":["생각을 묻는 질문이에요.","222쪽이에요.","바른 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
