INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_challenge#5','kor',2,2,'u7','L11','g2_2_kor_u7_L11_challenge','lesson_challenge','K2-2-u7-C12',3,'mc','auto','인물이 되어 정리한 말로 가장 알맞은 것은?',ARRAY['K2-2-u7-X07','K2-2-u7-X10']::text[],false,'{"seq":5,"concept":"K2-2-u7-C12","difficulty":3,"kind":"mc","stem":"인물이 되어 정리한 말로 가장 알맞은 것은?","options":[{"t":"「내가 만약 우철이라면 달걀보다 병아리가 자라는 모습을 보고 싶다고 할 거예요. 생명을 돌보는 일이 더 뜻깊기 때문이에요.」","correct":true},{"t":"「내가 만약 우철이라면…….」","mis":"K2-2-u7-X07"},{"t":"「우철이는 이상해요.」","mis":"K2-2-u7-X10"}],"explanation":["말과 까닭이에요.","222쪽이에요.","인물이 되어 봐요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_challenge#6','kor',2,2,'u7','L11','g2_2_kor_u7_L11_challenge','lesson_challenge','K2-2-u7-C13',3,'mc','auto','『국어』 225쪽 — ○표 한 문장 아래 글자를 모아 만든 문장은?',ARRAY['K2-2-u7-X13']::text[],false,'{"seq":6,"concept":"K2-2-u7-C13","difficulty":3,"kind":"mc","stem":"『국어』 225쪽 — ○표 한 문장 아래 글자를 모아 만든 문장은?","options":[{"t":"얘들아! 약속을 잘 지키자.","correct":true},{"t":"얘들아! 큼민 지키자.","mis":"K2-2-u7-X13"},{"t":"얘들아! 약속을 잊자.","mis":"K2-2-u7-X13"}],"explanation":["약속을 잘 지키자예요.","225쪽 예시 답안이에요.","생각 문장만 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_challenge#7','kor',2,2,'u7','L11','g2_2_kor_u7_L11_challenge','lesson_challenge','K2-2-u7-C9',3,'mc','auto','「생각을 몸으로 말해요」 놀이에서 「반려견이 용변을 보는 상황」에 대한 생각으로 알맞은 것은?',ARRAY['K2-2-u7-X14']::text[],false,'{"seq":7,"concept":"K2-2-u7-C9","difficulty":3,"kind":"mc","stem":"「생각을 몸으로 말해요」 놀이에서 「반려견이 용변을 보는 상황」에 대한 생각으로 알맞은 것은?","options":[{"t":"「반려견의 배설물은 주인이 치우자.」","correct":true},{"t":"「모르는 척 지나가자.」","mis":"K2-2-u7-X14"},{"t":"「반려견을 산책시키지 말자.」","mis":"K2-2-u7-X14"}],"explanation":["치우자예요.","지도서 305쪽이에요.","에티켓이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_challenge#8','kor',2,2,'u7','L11','g2_2_kor_u7_L11_challenge','lesson_challenge','K2-2-u7-C13',4,'sa','auto','「괜찮아」는 [괜○나]로 소리 나요. 빈칸 한 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u7-C13","difficulty":4,"kind":"sa","stem":"「괜찮아」는 [괜○나]로 소리 나요. 빈칸 한 글자를 쓰세요.","answer":["차"],"explanation":["[괜차나]예요.","226쪽이에요.","쓸 때는 괜찮아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_challenge#9','kor',2,2,'u7','L11','g2_2_kor_u7_L11_challenge','lesson_challenge','K2-2-u7-C12',4,'essay','teacher','「왜 책임이 필요하죠?」에서 되고 싶은 인물을 고르고, 「내가 만약 ~라면」 틀로 하고 싶은 말과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u7-C12","difficulty":4,"kind":"essay","stem":"「왜 책임이 필요하죠?」에서 되고 싶은 인물을 고르고, 「내가 만약 ~라면」 틀로 하고 싶은 말과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 내가 만약 선생님이라면 「병아리를 돌보는 방법부터 함께 배워 봐요.」라고 말할 거예요. 왜냐하면 잘 알아야 책임지고 돌볼 수 있기 때문이에요.","scoring_points":["인물을 골랐어요","하고 싶은 말과 까닭이 있어요"]},"explanation":["인물이 되어요.","222쪽이에요.","까닭과 함께요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_L11_challenge#10','kor',2,2,'u7','L11','g2_2_kor_u7_L11_challenge','lesson_challenge','K2-2-u7-C9',4,'essay','teacher','우리 학교에서 고치고 싶은 문제 하나를 골라 손 팻말 네 장(생각·까닭·경험·느낌)에 쓸 문장을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C9","difficulty":4,"kind":"essay","stem":"우리 학교에서 고치고 싶은 문제 하나를 골라 손 팻말 네 장(생각·까닭·경험·느낌)에 쓸 문장을 쓰세요.","answer_guide":{"answer":"예: 생각 — 급식실에서 줄을 서자. 까닭 — 새치기하면 다툼이 생기니까. 경험 — 줄이 엉켜 넘어질 뻔했어. 느낌 — 차례를 지키면 모두 기분이 좋아.","scoring_points":["네 가지 역할이 있어요","한 문제에 대한 글이에요"]},"explanation":["손 팻말이에요.","지도서 304쪽이에요.","모둠 활동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#1','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C1',1,'mc','auto','선생님께서 「민철이는 어떻게 생각하는지 발표해 보세요.」라고 하셨어요. 어떤 상황인가요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":1,"concept":"K2-2-u7-C1","difficulty":1,"kind":"mc","stem":"선생님께서 「민철이는 어떻게 생각하는지 발표해 보세요.」라고 하셨어요. 어떤 상황인가요?","options":[{"t":"수업 시간에 자신의 생각을 발표하는 상황","correct":true},{"t":"친구 그림에 칭찬 쪽지를 붙이는 상황","mis":"K2-2-u7-X06"},{"t":"책을 읽고 짝과 이야기하는 상황","mis":"K2-2-u7-X06"}],"explanation":["발표 상황이에요.","201쪽이에요.","그림 ㉮예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#2','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C3',1,'mc','auto','「반려견을 사랑한다면」의 제목으로 짐작한 글쓴이의 말은?',ARRAY['K2-2-u7-X14','K2-2-u7-X03']::text[],false,'{"seq":2,"concept":"K2-2-u7-C3","difficulty":1,"kind":"mc","stem":"「반려견을 사랑한다면」의 제목으로 짐작한 글쓴이의 말은?","options":[{"t":"반려견 에티켓을 지키자","correct":true},{"t":"반려견을 키우지 말자","mis":"K2-2-u7-X14"},{"t":"반려견 이름을 짓자","mis":"K2-2-u7-X03"}],"explanation":["에티켓이에요.","205쪽이에요.","제목을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#3','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C4',1,'mc','auto','「반려견을 사랑한다면」 글 ㉯의 중심 생각은?',ARRAY['K2-2-u7-X04']::text[],false,'{"seq":3,"concept":"K2-2-u7-C4","difficulty":1,"kind":"mc","stem":"「반려견을 사랑한다면」 글 ㉯의 중심 생각은?","options":[{"t":"반려견의 배설물은 주인이 치워야 한다.","correct":true},{"t":"그러면 그 자리에서 냄새가 나고 다른 사람이 배설물을 밟을 수도 있다.","mis":"K2-2-u7-X04"},{"t":"반려견이 산책 중 변을 봤을 때 모르는 척 그냥 가 버리는 사람이 있다.","mis":"K2-2-u7-X04"}],"explanation":["첫 문장이에요.","지도서 287쪽이에요.","뒷받침과 달라요."],"asset":{"type":"passage","lines":["반려견의 배설물은 주인이 치워야 한다.","반려견이 산책 중 변을 봤을 때 모르는 척 그냥 가 버리는 사람이 있다.","그러면 그 자리에서 냄새가 나고 다른 사람이 배설물을 밟을 수도 있다.","반려견과 산책할 때에는 비닐봉지와 집게 같은 도구를 챙겨야 한다."],"title":"「반려견을 사랑한다면」 글 ㉯"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#4','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C6',1,'mc','auto','반려견의 짖는 소리가 큰 피해를 줄 수 있는 곳으로 글에 나온 곳은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":4,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"반려견의 짖는 소리가 큰 피해를 줄 수 있는 곳으로 글에 나온 곳은?","options":[{"t":"도서관","correct":true},{"t":"운동장","mis":"K2-2-u7-X06"},{"t":"공원","mis":"K2-2-u7-X06"}],"explanation":["도서관이에요.","지도서 286쪽이에요.","글 ㉱예요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#5','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C9',1,'mc','auto','「뒤뜰에서 병아리를 키웁시다.」는 무엇에 해당하나요?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":5,"concept":"K2-2-u7-C9","difficulty":1,"kind":"mc","stem":"「뒤뜰에서 병아리를 키웁시다.」는 무엇에 해당하나요?","options":[{"t":"생각","correct":true},{"t":"느낌","mis":"K2-2-u7-X09"},{"t":"생각에 대한 까닭","mis":"K2-2-u7-X09"}],"explanation":["생각이에요.","216쪽이에요.","~합시다예요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#6','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C8',1,'mc','auto','발표할 때 알맞은 자세는?',ARRAY['K2-2-u7-X08']::text[],false,'{"seq":6,"concept":"K2-2-u7-C8","difficulty":1,"kind":"mc","stem":"발표할 때 알맞은 자세는?","options":[{"t":"친구들을 바라보며 또박또박 말해요","correct":true},{"t":"바닥을 보며 작게 말해요","mis":"K2-2-u7-X08"},{"t":"뒤돌아서 말해요","mis":"K2-2-u7-X08"}],"explanation":["바라보며 또박또박이에요.","210쪽이에요.","바른 자세예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#7','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C11',1,'mc','auto','봄솔이가 읽고 웃게 될 댓글은?',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":7,"concept":"K2-2-u7-C11","difficulty":1,"kind":"mc","stem":"봄솔이가 읽고 웃게 될 댓글은?","options":[{"t":"댓글 ㉠","correct":true},{"t":"댓글 ㉡","mis":"K2-2-u7-X11"},{"t":"둘 다 아니에요","mis":"K2-2-u7-X11"}],"explanation":["㉠이에요.","지도서 300쪽이에요.","공감해요."],"asset":{"type":"passage","lines":["봄솔이의 글: 쉬는 시간에 복도에서 뛰지 맙시다.","왜냐하면 친구와 부딪쳐 다칠 수 있기 때문입니다.","댓글 ㉠: 좋은 생각이야! 나도 지난주에 복도에서 부딪칠 뻔했어.","댓글 ㉡: 그걸 누가 몰라? 재미없어."],"title":"친구 글과 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#8','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C13',1,'mc','auto','「맑네」의 소리는?',ARRAY['K2-2-u7-X15']::text[],false,'{"seq":8,"concept":"K2-2-u7-C13","difficulty":1,"kind":"mc","stem":"「맑네」의 소리는?","options":[{"t":"[망네]","correct":true},{"t":"[말네]","mis":"K2-2-u7-X15"},{"t":"[맑네]","mis":"K2-2-u7-X15"}],"explanation":["[망네]예요.","226쪽이에요.","쓸 때는 맑네예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#9','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C5',2,'mc','auto','「반려견을 사랑한다면」에서 글쓴이의 생각은?',ARRAY['K2-2-u7-X05','K2-2-u7-X14']::text[],false,'{"seq":9,"concept":"K2-2-u7-C5","difficulty":2,"kind":"mc","stem":"「반려견을 사랑한다면」에서 글쓴이의 생각은?","options":[{"t":"반려견을 진심으로 사랑한다면 여러 가지 반려견 에티켓을 꼭 지켜야 한다","correct":true},{"t":"반려견의 배설물은 주인이 치워야 한다","mis":"K2-2-u7-X05"},{"t":"반려견은 무서운 동물이다","mis":"K2-2-u7-X14"}],"explanation":["모아서 정리해요.","206쪽이에요.","글 전체예요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#10','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C4',2,'match','auto','글과 중심 생각을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C4","difficulty":2,"kind":"match","stem":"글과 중심 생각을 이어 보세요.","pairs":[{"l":"글 ㉰","r":"반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다."},{"l":"글 ㉱","r":"반려견의 출입이 금지된 곳에는 반려견을 데리고 가지 않아야 한다."},{"l":"글 ㉲","r":"다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."}],"mis":"K2-2-u7-X04","explanation":["작은 글마다요.","205쪽이에요.","중심 생각이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#11','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C7',2,'mc','auto','글쓴이와 다른 생각을 알맞게 말한 것은?',ARRAY['K2-2-u7-X07']::text[],false,'{"seq":11,"concept":"K2-2-u7-C7","difficulty":2,"kind":"mc","stem":"글쓴이와 다른 생각을 알맞게 말한 것은?","options":[{"t":"「나는 줄넘기를 좋아하니까 줄넘기를 하고 싶어. 줄넘기도 몸에 좋으니까.」","correct":true},{"t":"「글쓴이는 틀렸어!」","mis":"K2-2-u7-X07"},{"t":"「달리기는 그냥 싫어.」","mis":"K2-2-u7-X07"}],"explanation":["까닭과 함께요.","209쪽이에요.","달라도 돼요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#12','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C10',2,'mc','auto','생각을 글로 나타낼 때 알맞은 표현은?',ARRAY['K2-2-u7-X10','K2-2-u7-X09']::text[],false,'{"seq":12,"concept":"K2-2-u7-C10","difficulty":2,"kind":"mc","stem":"생각을 글로 나타낼 때 알맞은 표현은?","options":[{"t":"「~합시다. 왜냐하면 ~때문입니다.」처럼 예의 바르게 써요","correct":true},{"t":"「~해! 짜증 나.」처럼 써요","mis":"K2-2-u7-X10"},{"t":"까닭은 빼요","mis":"K2-2-u7-X09"}],"explanation":["예의 바르게요.","216쪽이에요.","읽는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#13','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C12',2,'mc','auto','인물 의자에 앉은 「규빈」에게 할 질문으로 알맞은 것은?',ARRAY['K2-2-u7-X10','K2-2-u7-X12']::text[],false,'{"seq":13,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"인물 의자에 앉은 「규빈」에게 할 질문으로 알맞은 것은?","options":[{"t":"「규빈아, 병아리를 키우자고 한 까닭은 무엇이니?」","correct":true},{"t":"「너는 왜 그렇게 이상하니?」","mis":"K2-2-u7-X10"},{"t":"「아무거나 말해 봐.」","mis":"K2-2-u7-X12"}],"explanation":["생각을 묻는 질문이에요.","222쪽이에요.","바른 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#14','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C13',2,'mc','auto','다음 가운데 생각을 나타내는 문장은?',ARRAY['K2-2-u7-X13']::text[],false,'{"seq":14,"concept":"K2-2-u7-C13","difficulty":2,"kind":"mc","stem":"다음 가운데 생각을 나타내는 문장은?","options":[{"t":"물을 낭비하지 말자.","correct":true},{"t":"지금 다섯 시야.","mis":"K2-2-u7-X13"},{"t":"이 아이스크림은 오백 원이야.","mis":"K2-2-u7-X13"}],"explanation":["말자예요.","225쪽이에요.","~하자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#15','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C2',2,'mc','auto','생각을 말이나 글로 나타낼 때 중요한 것은?',ARRAY['K2-2-u7-X02']::text[],false,'{"seq":15,"concept":"K2-2-u7-C2","difficulty":2,"kind":"mc","stem":"생각을 말이나 글로 나타낼 때 중요한 것은?","options":[{"t":"나타내려는 내용과 나타내는 태도 모두","correct":true},{"t":"내용만 좋으면 돼요","mis":"K2-2-u7-X02"},{"t":"태도만 좋으면 돼요","mis":"K2-2-u7-X02"}],"explanation":["둘 다예요.","지도서 281쪽이에요.","내용과 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#16','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C6',2,'mc','auto','「왜 책임이 필요하죠?」에서 등장인물들은 무엇을 정하려고 하나요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":16,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"「왜 책임이 필요하죠?」에서 등장인물들은 무엇을 정하려고 하나요?","options":[{"t":"학교 뒤뜰에 무엇을 키울지","correct":true},{"t":"소풍 장소","mis":"K2-2-u7-X06"},{"t":"교실 벽 색깔","mis":"K2-2-u7-X06"}],"explanation":["뒤뜰 꾸미기예요.","215쪽이에요.","생각을 나눠요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
