INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#19','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C5',3,'ox','auto','글에서 중심 생각 하나만 찾으면 그것이 바로 글쓴이의 생각이다.',ARRAY['K2-2-u7-X05']::text[],false,'{"seq":19,"concept":"K2-2-u7-C5","difficulty":3,"kind":"ox","stem":"글에서 중심 생각 하나만 찾으면 그것이 바로 글쓴이의 생각이다.","answer":"X","reason_options":[{"t":"제목과 여러 중심 생각을 모아야 글 전체의 생각이 드러나서","correct":true},{"t":"중심 생각은 하나뿐이라서","mis":"K2-2-u7-X05"}],"mis":"K2-2-u7-X05","explanation":["모아야 해요.","지도서 284쪽이에요.","혼동하지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#20','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C6',3,'mc','auto','「반려견을 사랑한다면」을 읽고 할 생각으로 알맞은 것은?',ARRAY['K2-2-u7-X14']::text[],false,'{"seq":20,"concept":"K2-2-u7-C6","difficulty":3,"kind":"mc","stem":"「반려견을 사랑한다면」을 읽고 할 생각으로 알맞은 것은?","options":[{"t":"반려견과 함께 지내려면 주인이 지킬 약속이 있구나","correct":true},{"t":"반려견은 모두 없어져야 해","mis":"K2-2-u7-X14"},{"t":"반려견을 키우는 사람은 나빠","mis":"K2-2-u7-X14"}],"explanation":["지킬 약속이에요.","지도서 285쪽이에요.","편견이 아니에요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#21','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C9',3,'mc','auto','다육 식물 글에서 「생각에 대한 까닭」에 해당하는 문장은?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":21,"concept":"K2-2-u7-C9","difficulty":3,"kind":"mc","stem":"다육 식물 글에서 「생각에 대한 까닭」에 해당하는 문장은?","options":[{"t":"왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","correct":true},{"t":"우리 교실에서 다육 식물을 키우면 좋겠습니다.","mis":"K2-2-u7-X09"},{"t":"예전에 집에서 키웠는데 물을 많이 주지 않아도 잘 자랐어요.","mis":"K2-2-u7-X09"}],"explanation":["왜냐하면이에요.","224쪽이에요.","까닭이에요."],"asset":{"type":"passage","lines":["우리 교실에서 다육 식물을 키우면 좋겠습니다.","왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","예전에 집에서 키웠는데 물을 많이 주지 않아도 잘 자랐어요.","다육 식물은 귀엽게 생겨서 교실 분위기를 더 밝게 만들어 줄 거예요."],"title":"『국어』 224쪽 정리하기 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#22','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C11',3,'mc','auto','칭찬하는 댓글로 가장 알맞은 것은?',ARRAY['K2-2-u7-X11','K2-2-u7-X10']::text[],false,'{"seq":22,"concept":"K2-2-u7-C11","difficulty":3,"kind":"mc","stem":"칭찬하는 댓글로 가장 알맞은 것은?","options":[{"t":"「까닭이 분명해서 네 생각이 잘 이해돼.」","correct":true},{"t":"「잘했네.」","mis":"K2-2-u7-X11"},{"t":"「내 글이 더 좋아.」","mis":"K2-2-u7-X10"}],"explanation":["구체적인 칭찬이에요.","지도서 301쪽이에요.","무엇이 좋은지요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#23','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C2',4,'sa','auto','생각을 말이나 글로 나타낼 때 중요한 두 가지는 「내용」과 「○○」예요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u7-C2","difficulty":4,"kind":"sa","stem":"생각을 말이나 글로 나타낼 때 중요한 두 가지는 「내용」과 「○○」예요. 빈칸 두 글자를 쓰세요.","answer":["태도"],"explanation":["태도예요.","지도서 281쪽이에요.","내용과 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#24','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C10',4,'essay','teacher','지도서 308~309쪽 평가 — 무엇에 대한 생각인지, 그 까닭, 관련한 경험을 넣고 상대를 배려하는 표현으로 생각을 표현하는 글을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u7-C10","difficulty":4,"kind":"essay","stem":"지도서 308~309쪽 평가 — 무엇에 대한 생각인지, 그 까닭, 관련한 경험을 넣고 상대를 배려하는 표현으로 생각을 표현하는 글을 쓰세요.","answer_guide":{"answer":"예: 쉬는 시간에 복도에서 걸어 다닙시다. 왜냐하면 뛰다가 친구와 부딪쳐 다칠 수 있기 때문입니다. 저도 모퉁이에서 친구와 부딪칠 뻔했습니다. 모두 안전하면 좋겠습니다.","scoring_points":["생각과 까닭이 있어요","경험이 있어요","배려하는 표현이에요"]},"explanation":["생각을 나타내는 글이에요.","지도서 309쪽이에요.","허용적으로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_a#25','kor',2,2,'u7','','g2_2_kor_u7_review_a','unit_review','K2-2-u7-C5',4,'essay','teacher','지도서 310~311쪽 평가 — 제목과 글 ㉮·㉯의 중심 생각을 쓰고, 글쓴이의 생각을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u7-C5","difficulty":4,"kind":"essay","stem":"지도서 310~311쪽 평가 — 제목과 글 ㉮·㉯의 중심 생각을 쓰고, 글쓴이의 생각을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 제목 — 외출하고 돌아온 뒤에는 손을 꼭 씻자. ㉮ — 자신의 건강을 위해 외출 뒤 손을 꼭 씻어야 한다. ㉯ — 외출 뒤 손 씻기는 가족의 건강을 생각하는 행동이다. 글쓴이의 생각 — 나와 가족의 건강을 위해 외출 뒤에는 손을 꼭 씻자.","scoring_points":["제목과 중심 생각을 찾았어요","모아서 글쓴이의 생각을 썼어요"]},"explanation":["모아서 정리해요.","지도서 310쪽이에요.","제목과 중심 생각이에요."],"asset":{"type":"passage","lines":["㉮ 자신의 건강을 위해 외출하고 돌아온 뒤에는 손을 꼭 씻어야 해요.","여러 물건을 만지는 사이에 손에 세균이 달라붙었기 때문이에요.","㉯ 그리고 외출 뒤 손 씻기는 가족의 건강을 생각하는 행동이에요.","씻지 않은 손으로 같이 쓰는 물건을 만지면 세균이 옮겨 붙을 수 있어요."],"title":"지도서 311쪽 평가 「외출하고 돌아온 뒤에는 손을 꼭 씻자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#1','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C1',1,'mc','auto','친구 그림 옆에 「밤하늘을 예쁘게 표현했구나.」라고 붙였어요. 어떤 상황인가요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":1,"concept":"K2-2-u7-C1","difficulty":1,"kind":"mc","stem":"친구 그림 옆에 「밤하늘을 예쁘게 표현했구나.」라고 붙였어요. 어떤 상황인가요?","options":[{"t":"친구의 그림에 칭찬하는 글을 붙이는 상황","correct":true},{"t":"수업 시간에 발표하는 상황","mis":"K2-2-u7-X06"},{"t":"모둠 대화 상황","mis":"K2-2-u7-X06"}],"explanation":["칭찬 쪽지예요.","201쪽이에요.","그림 ㉯예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#2','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C3',1,'mc','auto','「아침에 운동장을 달려요」의 제목으로 짐작한 글쓴이의 말은?',ARRAY['K2-2-u7-X03']::text[],false,'{"seq":2,"concept":"K2-2-u7-C3","difficulty":1,"kind":"mc","stem":"「아침에 운동장을 달려요」의 제목으로 짐작한 글쓴이의 말은?","options":[{"t":"아침에 운동장을 달리자","correct":true},{"t":"운동장을 청소하자","mis":"K2-2-u7-X03"},{"t":"아침밥을 먹자","mis":"K2-2-u7-X03"}],"explanation":["달리자예요.","208쪽이에요.","제목을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#3','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C4',1,'mc','auto','「반려견을 사랑한다면」 글 ㉰의 중심 생각은?',ARRAY['K2-2-u7-X04']::text[],false,'{"seq":3,"concept":"K2-2-u7-C4","difficulty":1,"kind":"mc","stem":"「반려견을 사랑한다면」 글 ㉰의 중심 생각은?","options":[{"t":"반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","correct":true},{"t":"반려견을 목줄 없이 풀어놓는 것은 이들에게 위협적인 행동이 될 수 있다.","mis":"K2-2-u7-X04"},{"t":"개에게 물렸던 사람이나 개를 무서워하는 어린이는 공포를 느낄 수 있다.","mis":"K2-2-u7-X04"}],"explanation":["첫 문장이에요.","지도서 288쪽이에요.","뒷받침과 달라요."],"asset":{"type":"passage","lines":["반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","개에게 물렸던 사람이나 개를 무서워하는 어린이는 공포를 느낄 수 있다.","반려견을 목줄 없이 풀어놓는 것은 이들에게 위협적인 행동이 될 수 있다."],"title":"「반려견을 사랑한다면」 글 ㉰"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#4','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C6',1,'mc','auto','반려견의 배설물은 누가 치워야 한다고 했나요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":4,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"반려견의 배설물은 누가 치워야 한다고 했나요?","options":[{"t":"반려견의 주인","correct":true},{"t":"지나가는 사람","mis":"K2-2-u7-X06"},{"t":"청소하는 분","mis":"K2-2-u7-X06"}],"explanation":["주인이에요.","지도서 286쪽이에요.","글 ㉯예요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#5','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C9',1,'mc','auto','「왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.」는 무엇에 해당하나요?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":5,"concept":"K2-2-u7-C9","difficulty":1,"kind":"mc","stem":"「왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.」는 무엇에 해당하나요?","options":[{"t":"생각에 대한 까닭","correct":true},{"t":"느낌","mis":"K2-2-u7-X09"},{"t":"경험이나 알고 있는 것","mis":"K2-2-u7-X09"}],"explanation":["까닭이에요.","216쪽이에요.","왜냐하면이에요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#6','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C8',1,'mc','auto','친구의 발표를 들을 때 알맞은 태도는?',ARRAY['K2-2-u7-X08']::text[],false,'{"seq":6,"concept":"K2-2-u7-C8","difficulty":1,"kind":"mc","stem":"친구의 발표를 들을 때 알맞은 태도는?","options":[{"t":"존중하는 마음으로 귀 기울여 들어요","correct":true},{"t":"친구가 말할 때 끼어들어요","mis":"K2-2-u7-X08"},{"t":"다른 책을 읽어요","mis":"K2-2-u7-X08"}],"explanation":["귀 기울여요.","210쪽이에요.","존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#7','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C11',1,'mc','auto','댓글 알림판 활동에서 가장 먼저 할 일은?',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":7,"concept":"K2-2-u7-C11","difficulty":1,"kind":"mc","stem":"댓글 알림판 활동에서 가장 먼저 할 일은?","options":[{"t":"책상 위에 자신이 쓴 글을 펼쳐 둔다","correct":true},{"t":"붙임쪽지를 붙인다","mis":"K2-2-u7-X11"},{"t":"붙임쪽지에 생각을 쓴다","mis":"K2-2-u7-X11"}],"explanation":["펼쳐 둬요.","220쪽이에요.","첫째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#8','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C13',1,'mc','auto','「괜찮아」의 소리는?',ARRAY['K2-2-u7-X15']::text[],false,'{"seq":8,"concept":"K2-2-u7-C13","difficulty":1,"kind":"mc","stem":"「괜찮아」의 소리는?","options":[{"t":"[괜차나]","correct":true},{"t":"[갠차나]","mis":"K2-2-u7-X15"},{"t":"[괜찬아]","mis":"K2-2-u7-X15"}],"explanation":["[괜차나]예요.","226쪽이에요.","쓸 때는 괜찮아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#9','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C5',2,'mc','auto','「아침에 운동장을 달려요」에서 글쓴이의 생각은?',ARRAY['K2-2-u7-X05']::text[],false,'{"seq":9,"concept":"K2-2-u7-C5","difficulty":2,"kind":"mc","stem":"「아침에 운동장을 달려요」에서 글쓴이의 생각은?","options":[{"t":"아침에 운동장을 달리자.","correct":true},{"t":"시원한 공기가 가득하다.","mis":"K2-2-u7-X05"},{"t":"몸무게를 조절할 수 있다.","mis":"K2-2-u7-X05"}],"explanation":["달리자예요.","209쪽이에요.","모아서 정리해요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#10','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C9',2,'match','auto','규빈이 글의 문장과 역할을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C9","difficulty":2,"kind":"match","stem":"규빈이 글의 문장과 역할을 이어 보세요.","pairs":[{"l":"뒤뜰에서 병아리를 키웁시다.","r":"생각"},{"l":"책임감을 기를 수 있기 때문입니다.","r":"생각에 대한 까닭"},{"l":"책에서 보았습니다.","r":"경험이나 알고 있는 것"},{"l":"정말 뿌듯할 것 같습니다.","r":"느낌"}],"mis":"K2-2-u7-X09","explanation":["네 가지예요.","216쪽이에요.","생각을 나타내는 글이에요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#11','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C7',2,'mc','auto','다육 식물 글을 읽고 내 생각을 알맞게 쓴 것은?',ARRAY['K2-2-u7-X07']::text[],false,'{"seq":11,"concept":"K2-2-u7-C7","difficulty":2,"kind":"mc","stem":"다육 식물 글을 읽고 내 생각을 알맞게 쓴 것은?","options":[{"t":"「우리 교실은 햇빛이 잘 들지 않아 다육 식물을 키우기 어려울 것 같습니다.」","correct":true},{"t":"「싫어요.」","mis":"K2-2-u7-X07"},{"t":"「글쓴이는 틀렸어요.」","mis":"K2-2-u7-X07"}],"explanation":["까닭과 함께요.","224쪽 예시 답안이에요.","다른 생각도 돼요."],"asset":{"type":"passage","lines":["우리 교실에서 다육 식물을 키우면 좋겠습니다.","왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","예전에 집에서 키웠는데 물을 많이 주지 않아도 잘 자랐어요.","다육 식물은 귀엽게 생겨서 교실 분위기를 더 밝게 만들어 줄 거예요."],"title":"『국어』 224쪽 정리하기 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#12','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C10',2,'mc','auto','상대를 존중하며 생각을 바르게 나타낸 것은?',ARRAY['K2-2-u7-X10']::text[],false,'{"seq":12,"concept":"K2-2-u7-C10","difficulty":2,"kind":"mc","stem":"상대를 존중하며 생각을 바르게 나타낸 것은?","options":[{"t":"「문을 잘 닫고 다니자는 규칙을 만듭시다. 문 앞에 앉은 친구가 불편할 수 있기 때문입니다.」","correct":true},{"t":"「너희가 문을 안 닫아서 매번 내가 닫잖아.」","mis":"K2-2-u7-X10"},{"t":"「문 안 닫는 애들 때문에 짜증 나.」","mis":"K2-2-u7-X10"}],"explanation":["존중하는 표현이에요.","국어활동 96쪽이에요.","효은이 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#13','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C12',2,'mc','auto','활동할 이야기를 고를 때 알맞은 것은?',ARRAY['K2-2-u7-X12']::text[],false,'{"seq":13,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"활동할 이야기를 고를 때 알맞은 것은?","options":[{"t":"등장인물의 생각이 분명히 드러나는 이야기","correct":true},{"t":"글자가 가장 많은 이야기","mis":"K2-2-u7-X12"},{"t":"그림이 없는 이야기","mis":"K2-2-u7-X12"}],"explanation":["생각이 드러나요.","지도서 302쪽이에요.","인물이 되어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#14','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C13',2,'mc','auto','다음 가운데 생각을 나타내는 문장은?',ARRAY['K2-2-u7-X13']::text[],false,'{"seq":14,"concept":"K2-2-u7-C13","difficulty":2,"kind":"mc","stem":"다음 가운데 생각을 나타내는 문장은?","options":[{"t":"주말에 단풍을 보러 가는 건 어때요?","correct":true},{"t":"지금 다섯 시야.","mis":"K2-2-u7-X13"},{"t":"이 아이스크림은 오백 원이야.","mis":"K2-2-u7-X13"}],"explanation":["~는 어때요예요.","225쪽이에요.","제안이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#15','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C2',2,'mc','auto','회의에서 생각을 말할 때 알맞은 태도는?',ARRAY['K2-2-u7-X01']::text[],false,'{"seq":15,"concept":"K2-2-u7-C2","difficulty":2,"kind":"mc","stem":"회의에서 생각을 말할 때 알맞은 태도는?","options":[{"t":"다른 생각도 귀 기울여 듣고 내 생각을 까닭과 함께 말해요","correct":true},{"t":"「무슨 소리!」 하고 무시해요","mis":"K2-2-u7-X01"},{"t":"내 생각만 여러 번 말해요","mis":"K2-2-u7-X01"}],"explanation":["듣고 말해요.","지도서 282쪽이에요.","존중해요."],"asset":{"type":"speech","turns":[{"who":"쥐 1","text":"누가 고양이 목에 방울을 달기만 하면 고양이 걱정 없이 지낼 수 있습니다!"},{"who":"쥐 2","text":"무슨 소리! 우리가 힘을 합쳐 고양이와 싸워야 합니다."},{"who":"쥐 3","text":"그러지 말고 평화롭게 고양이와 대화로 풀어 보는 것은 어떨까요?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#16','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C6',2,'mc','auto','규빈이가 병아리를 키우자고 한 까닭은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":16,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"규빈이가 병아리를 키우자고 한 까닭은?","options":[{"t":"병아리가 자라며 닭이 되는 과정을 볼 수 있어서","correct":true},{"t":"달걀을 먹을 수 있어서","mis":"K2-2-u7-X06"},{"t":"강아지보다 작아서","mis":"K2-2-u7-X06"}],"explanation":["닭이 되는 과정이에요.","215쪽이에요.","규빈이 말이에요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
