INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#19','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C7',3,'ox','auto','글쓴이의 생각과 다른 생각을 말하면 안 된다.',ARRAY['K2-2-u7-X07']::text[],false,'{"seq":19,"concept":"K2-2-u7-C7","difficulty":3,"kind":"ox","stem":"글쓴이의 생각과 다른 생각을 말하면 안 된다.","answer":"X","reason_options":[{"t":"글쓴이와 다른 생각도 까닭과 함께 말할 수 있어서","correct":true},{"t":"글쓴이의 생각이 정답이라서","mis":"K2-2-u7-X07"}],"mis":"K2-2-u7-X07","explanation":["다른 생각도 돼요.","209쪽이에요.","까닭과 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#20','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C4',3,'mc','auto','「외출하고 돌아온 뒤에는 손을 꼭 씻자」 글 ㉯의 중심 생각은?',ARRAY['K2-2-u7-X04']::text[],false,'{"seq":20,"concept":"K2-2-u7-C4","difficulty":3,"kind":"mc","stem":"「외출하고 돌아온 뒤에는 손을 꼭 씻자」 글 ㉯의 중심 생각은?","options":[{"t":"외출 뒤 손 씻기는 가족의 건강을 생각하는 행동이에요.","correct":true},{"t":"씻지 않은 손으로 물건을 만지면 세균이 옮겨 붙을 수 있어요.","mis":"K2-2-u7-X04"},{"t":"손에 세균이 달라붙었기 때문이에요.","mis":"K2-2-u7-X04"}],"explanation":["첫 문장이에요.","지도서 311쪽이에요.","중심 생각이에요."],"asset":{"type":"passage","lines":["㉮ 자신의 건강을 위해 외출하고 돌아온 뒤에는 손을 꼭 씻어야 해요.","여러 물건을 만지는 사이에 손에 세균이 달라붙었기 때문이에요.","㉯ 그리고 외출 뒤 손 씻기는 가족의 건강을 생각하는 행동이에요.","씻지 않은 손으로 같이 쓰는 물건을 만지면 세균이 옮겨 붙을 수 있어요."],"title":"지도서 311쪽 평가 「외출하고 돌아온 뒤에는 손을 꼭 씻자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#21','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C9',3,'mc','auto','다육 식물 글에서 「경험이나 알고 있는 것」에 해당하는 문장은?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":21,"concept":"K2-2-u7-C9","difficulty":3,"kind":"mc","stem":"다육 식물 글에서 「경험이나 알고 있는 것」에 해당하는 문장은?","options":[{"t":"예전에 집에서 키웠는데 물을 많이 주지 않아도 잘 자랐어요.","correct":true},{"t":"우리 교실에서 다육 식물을 키우면 좋겠습니다.","mis":"K2-2-u7-X09"},{"t":"왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","mis":"K2-2-u7-X09"}],"explanation":["경험이에요.","224쪽이에요.","예전에 키웠어요."],"asset":{"type":"passage","lines":["우리 교실에서 다육 식물을 키우면 좋겠습니다.","왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","예전에 집에서 키웠는데 물을 많이 주지 않아도 잘 자랐어요.","다육 식물은 귀엽게 생겨서 교실 분위기를 더 밝게 만들어 줄 거예요."],"title":"『국어』 224쪽 정리하기 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#22','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C11',3,'mc','auto','친구 글에 궁금한 점을 묻는 댓글로 알맞은 것은?',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":22,"concept":"K2-2-u7-C11","difficulty":3,"kind":"mc","stem":"친구 글에 궁금한 점을 묻는 댓글로 알맞은 것은?","options":[{"t":"「좋은 생각이야. 그런데 계단에서는 어떻게 하면 좋을까?」","correct":true},{"t":"「그걸 누가 몰라?」","mis":"K2-2-u7-X11"},{"t":"「재미없어.」","mis":"K2-2-u7-X11"}],"explanation":["궁금한 점이에요.","220쪽이에요.","물어볼 수 있어요."],"asset":{"type":"passage","lines":["봄솔이의 글: 쉬는 시간에 복도에서 뛰지 맙시다.","왜냐하면 친구와 부딪쳐 다칠 수 있기 때문입니다.","댓글 ㉠: 좋은 생각이야! 나도 지난주에 복도에서 부딪칠 뻔했어.","댓글 ㉡: 그걸 누가 몰라? 재미없어."],"title":"친구 글과 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#23','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C3',4,'sa','auto','글쓴이의 생각을 파악하려면 글의 ○○을 반드시 확인해야 해요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u7-C3","difficulty":4,"kind":"sa","stem":"글쓴이의 생각을 파악하려면 글의 ○○을 반드시 확인해야 해요. 빈칸 두 글자를 쓰세요.","answer":["제목"],"explanation":["제목이에요.","지도서 287쪽이에요.","생각을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#24','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C7',4,'essay','teacher','「아침에 운동장을 달려요」를 읽고 글쓴이의 생각에 대한 자신의 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u7-C7","difficulty":4,"kind":"essay","stem":"「아침에 운동장을 달려요」를 읽고 글쓴이의 생각에 대한 자신의 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 나도 아침에 운동장을 달리고 싶다. 달리고 나면 기분이 상쾌해졌던 적이 있기 때문이다.","scoring_points":["글쓴이의 생각을 알고 있어요","내 생각과 까닭이 있어요"]},"explanation":["까닭과 함께요.","209쪽이에요.","같거나 달라도 돼요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_b#25','kor',2,2,'u7','','g2_2_kor_u7_review_b','unit_review','K2-2-u7-C5',4,'essay','teacher','「반려견을 사랑한다면」의 제목과 중심 생각을 모아 글쓴이의 생각을 쓰고, 그에 대한 내 생각을 한 문장 더 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u7-C5","difficulty":4,"kind":"essay","stem":"「반려견을 사랑한다면」의 제목과 중심 생각을 모아 글쓴이의 생각을 쓰고, 그에 대한 내 생각을 한 문장 더 쓰세요.","answer_guide":{"answer":"예: 글쓴이의 생각 — 다른 사람과 반려견을 위해 에티켓을 지키자. 내 생각 — 나도 강아지를 산책시킬 때 꼭 봉투를 챙기겠다.","scoring_points":["글쓴이의 생각을 썼어요","내 생각을 썼어요"]},"explanation":["파악하고 생각해요.","206쪽이에요.","두 가지예요."],"asset":{"type":"passage","lines":["㉮ 반려견과 야외로 나갈 때 꼭 지켜야 하는 에티켓이 있다.","㉯ 첫째, 반려견의 배설물은 주인이 치워야 한다.","㉰ 둘째, 반려견을 야외로 데리고 나갈 때에는 목줄을 채워야 한다.","㉱ 셋째, 반려견의 출입이 금지된 곳에는 데리고 가지 않아야 한다.","㉲ 다른 사람과 내 반려견을 위해 에티켓을 꼭 지키도록 하자."],"title":"『국어』 202~204쪽 「반려견을 사랑한다면」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#1','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C1',1,'mc','auto','「글쓴이는 친구 사이에 믿음이 중요하다고 말하고 싶었던 것 같아.」는 어떤 상황의 말인가요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":1,"concept":"K2-2-u7-C1","difficulty":1,"kind":"mc","stem":"「글쓴이는 친구 사이에 믿음이 중요하다고 말하고 싶었던 것 같아.」는 어떤 상황의 말인가요?","options":[{"t":"책을 읽고 짝과 이야기를 나누는 상황","correct":true},{"t":"친구 그림에 칭찬 쪽지를 붙이는 상황","mis":"K2-2-u7-X06"},{"t":"모둠 규칙을 정하는 상황","mis":"K2-2-u7-X06"}],"explanation":["책 이야기예요.","201쪽이에요.","그림 ㉰예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#2','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C3',1,'mc','auto','「외출하고 돌아온 뒤에는 손을 꼭 씻자」의 제목으로 짐작한 글쓴이의 말은?',ARRAY['K2-2-u7-X03']::text[],false,'{"seq":2,"concept":"K2-2-u7-C3","difficulty":1,"kind":"mc","stem":"「외출하고 돌아온 뒤에는 손을 꼭 씻자」의 제목으로 짐작한 글쓴이의 말은?","options":[{"t":"외출 뒤에는 손을 씻자","correct":true},{"t":"외출하지 말자","mis":"K2-2-u7-X03"},{"t":"물을 아끼자","mis":"K2-2-u7-X03"}],"explanation":["손을 씻자예요.","지도서 311쪽이에요.","제목에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#3','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C4',1,'mc','auto','「아침에 운동장을 달려요」 글 ㉯의 중심 생각은?',ARRAY['K2-2-u7-X04','K2-2-u7-X06']::text[],false,'{"seq":3,"concept":"K2-2-u7-C4","difficulty":1,"kind":"mc","stem":"「아침에 운동장을 달려요」 글 ㉯의 중심 생각은?","options":[{"t":"아침에 운동장을 달리면 기분이 좋아져요.","correct":true},{"t":"시원한 아침 공기는 스트레스를 사라지게 해 줘요.","mis":"K2-2-u7-X04"},{"t":"운동장에는 친구들이 많아요.","mis":"K2-2-u7-X06"}],"explanation":["첫째 다음이에요.","208쪽이에요.","중심 생각이에요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#4','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C6',1,'mc','auto','「아침에 운동장을 달려요」를 쓴 사람은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":4,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"「아침에 운동장을 달려요」를 쓴 사람은?","options":[{"t":"2학년 3반 이채영","correct":true},{"t":"2학년 3반 규빈","mis":"K2-2-u7-X06"},{"t":"선생님","mis":"K2-2-u7-X06"}],"explanation":["이채영이에요.","207쪽이에요.","글 ㉮예요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#5','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C9',1,'mc','auto','「병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.」는 무엇에 해당하나요?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":5,"concept":"K2-2-u7-C9","difficulty":1,"kind":"mc","stem":"「병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.」는 무엇에 해당하나요?","options":[{"t":"경험이나 알고 있는 것","correct":true},{"t":"생각","mis":"K2-2-u7-X09"},{"t":"느낌","mis":"K2-2-u7-X09"}],"explanation":["알고 있는 것이에요.","216쪽이에요.","책에서 봤어요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
