INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#7','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C11',1,'mc','auto','댓글을 쓸 때 생각해야 할 것은?',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":7,"concept":"K2-2-u7-C11","difficulty":1,"kind":"mc","stem":"댓글을 쓸 때 생각해야 할 것은?","options":[{"t":"댓글을 읽을 친구의 마음","correct":true},{"t":"댓글의 글자 수","mis":"K2-2-u7-X11"},{"t":"붙임쪽지 색깔","mis":"K2-2-u7-X11"}],"explanation":["친구의 마음이에요.","220쪽이에요.","배려해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#8','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C13',1,'mc','auto','「숲이」의 소리는?',ARRAY['K2-2-u7-X15']::text[],false,'{"seq":8,"concept":"K2-2-u7-C13","difficulty":1,"kind":"mc","stem":"「숲이」의 소리는?","options":[{"t":"[수피]","correct":true},{"t":"[숩피]","mis":"K2-2-u7-X15"},{"t":"[숲이]","mis":"K2-2-u7-X15"}],"explanation":["[수피]예요.","226쪽이에요.","받침이 넘어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#9','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C5',2,'mc','auto','이 글에서 글쓴이의 생각은?',ARRAY['K2-2-u7-X05']::text[],false,'{"seq":9,"concept":"K2-2-u7-C5","difficulty":2,"kind":"mc","stem":"이 글에서 글쓴이의 생각은?","options":[{"t":"외출하고 돌아온 뒤에는 손을 꼭 씻자","correct":true},{"t":"손에는 세균이 많다","mis":"K2-2-u7-X05"},{"t":"가족과 물건을 같이 쓴다","mis":"K2-2-u7-X05"}],"explanation":["손을 씻자예요.","지도서 311쪽이에요.","제목과 중심 생각이에요."],"asset":{"type":"passage","lines":["㉮ 자신의 건강을 위해 외출하고 돌아온 뒤에는 손을 꼭 씻어야 해요.","여러 물건을 만지는 사이에 손에 세균이 달라붙었기 때문이에요.","㉯ 그리고 외출 뒤 손 씻기는 가족의 건강을 생각하는 행동이에요.","씻지 않은 손으로 같이 쓰는 물건을 만지면 세균이 옮겨 붙을 수 있어요."],"title":"지도서 311쪽 평가 「외출하고 돌아온 뒤에는 손을 꼭 씻자」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
