INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#13','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C12',2,'mc','auto','「그럼 돌아가면서 돌볼게요.」에서 규빈이의 생각은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":13,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"「그럼 돌아가면서 돌볼게요.」에서 규빈이의 생각은?","options":[{"t":"돌보미를 정해 병아리를 돌아가며 책임지고 돌보자","correct":true},{"t":"달걀을 먹자","mis":"K2-2-u7-X06"},{"t":"병아리는 키우지 말자","mis":"K2-2-u7-X06"}],"explanation":["함께 돌보자예요.","214쪽이에요.","규빈이 말이에요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
