INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#21','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C8',3,'mc','auto','말하기가 떨리는 친구가 발표할 때 듣는 친구들이 할 일은?',ARRAY['K2-2-u7-X08']::text[],false,'{"seq":21,"concept":"K2-2-u7-C8","difficulty":3,"kind":"mc","stem":"말하기가 떨리는 친구가 발표할 때 듣는 친구들이 할 일은?","options":[{"t":"조용히 바라보며 고개를 끄덕여 줘요","correct":true},{"t":"「빨리 말해!」라고 재촉해요","mis":"K2-2-u7-X08"},{"t":"옆 친구와 떠들어요","mis":"K2-2-u7-X08"}],"explanation":["편하게 들어 줘요.","지도서 292쪽이에요.","허용적인 분위기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#22','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C10',3,'mc','auto','질문이나 느낌을 댓글로 쓸 때에도 함께 쓰면 좋은 것은?',ARRAY['K2-2-u7-X10','K2-2-u7-X11']::text[],false,'{"seq":22,"concept":"K2-2-u7-C10","difficulty":3,"kind":"mc","stem":"질문이나 느낌을 댓글로 쓸 때에도 함께 쓰면 좋은 것은?","options":[{"t":"그렇게 생각한 까닭이나 경험","correct":true},{"t":"친구의 별명","mis":"K2-2-u7-X10"},{"t":"「끝」이라는 글자","mis":"K2-2-u7-X11"}],"explanation":["까닭과 경험이에요.","지도서 301쪽이에요.","생각을 나타내는 글 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#23','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C9',4,'sa','auto','생각을 나타내는 글에는 생각, 생각에 대한 까닭, 경험이나 알고 있는 것, 그리고 ○○이 들어가요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u7-C9","difficulty":4,"kind":"sa","stem":"생각을 나타내는 글에는 생각, 생각에 대한 까닭, 경험이나 알고 있는 것, 그리고 ○○이 들어가요. 빈칸 두 글자를 쓰세요.","answer":["느낌"],"explanation":["느낌이에요.","216쪽이에요.","네 가지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#24','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C7',4,'essay','teacher','다육 식물 글을 읽고 글쓴이의 생각에 대한 자신의 생각을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u7-C7","difficulty":4,"kind":"essay","stem":"다육 식물 글을 읽고 글쓴이의 생각에 대한 자신의 생각을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 다육 식물은 햇빛을 오래 봐야 하는데 우리 교실은 햇빛이 잘 들지 않아서 키우기 어려울 것 같다. 시들면 친구들이 속상할 것이다.","scoring_points":["글쓴이의 생각에 대한 내 생각이에요","까닭이 있어요"]},"explanation":["까닭과 함께요.","224쪽 예시 답안이에요.","다른 생각도 돼요."],"asset":{"type":"passage","lines":["우리 교실에서 다육 식물을 키우면 좋겠습니다.","왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","예전에 집에서 키웠는데 물을 많이 주지 않아도 잘 자랐어요.","다육 식물은 귀엽게 생겨서 교실 분위기를 더 밝게 만들어 줄 거예요."],"title":"『국어』 224쪽 정리하기 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_c#25','kor',2,2,'u7','','g2_2_kor_u7_review_c','unit_review','K2-2-u7-C12',4,'essay','teacher','「왜 책임이 필요하죠?」에서 되고 싶은 인물을 고르고, 「내가 만약 ~라면」 틀로 하고 싶은 말과 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u7-C12","difficulty":4,"kind":"essay","stem":"「왜 책임이 필요하죠?」에서 되고 싶은 인물을 고르고, 「내가 만약 ~라면」 틀로 하고 싶은 말과 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 내가 만약 다혜라면 돌보미를 하겠다고 손을 들 거예요. 병아리를 정말 키우고 싶었기 때문이에요.","scoring_points":["인물을 골랐어요","하고 싶은 말과 까닭이 있어요"]},"explanation":["인물이 되어요.","222쪽이에요.","까닭과 함께요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#1','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C1',1,'mc','auto','「우리 모둠 활동 규칙을 무엇으로 정하면 좋을까?」는 어떤 상황의 말인가요?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":1,"concept":"K2-2-u7-C1","difficulty":1,"kind":"mc","stem":"「우리 모둠 활동 규칙을 무엇으로 정하면 좋을까?」는 어떤 상황의 말인가요?","options":[{"t":"모둠 대화에서 자신의 생각을 말하는 상황","correct":true},{"t":"수업 시간에 발표하는 상황","mis":"K2-2-u7-X06"},{"t":"책을 읽고 짝과 이야기하는 상황","mis":"K2-2-u7-X06"}],"explanation":["모둠 대화예요.","201쪽이에요.","그림 ㉱예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#2','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C3',1,'mc','auto','「왜 공공장소에서 질서를 지켜야 할까요?」의 제목으로 짐작한 글쓴이의 말은?',ARRAY['K2-2-u7-X03']::text[],false,'{"seq":2,"concept":"K2-2-u7-C3","difficulty":1,"kind":"mc","stem":"「왜 공공장소에서 질서를 지켜야 할까요?」의 제목으로 짐작한 글쓴이의 말은?","options":[{"t":"공공장소에서 질서를 지키자","correct":true},{"t":"공공장소에 가지 말자","mis":"K2-2-u7-X03"},{"t":"급식을 먼저 먹자","mis":"K2-2-u7-X03"}],"explanation":["질서를 지키자예요.","지도서 287쪽이에요.","제목에 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#3','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C4',1,'mc','auto','「아침에 운동장을 달려요」 글 ㉰의 중심 생각은?',ARRAY['K2-2-u7-X04','K2-2-u7-X06']::text[],false,'{"seq":3,"concept":"K2-2-u7-C4","difficulty":1,"kind":"mc","stem":"「아침에 운동장을 달려요」 글 ㉰의 중심 생각은?","options":[{"t":"아침에 운동장을 달리면 더 건강해져요.","correct":true},{"t":"점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","mis":"K2-2-u7-X04"},{"t":"아침 공기는 시원해요.","mis":"K2-2-u7-X06"}],"explanation":["둘째 다음이에요.","208쪽이에요.","중심 생각이에요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#4','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C6',1,'mc','auto','아침 운동장에 가득한 것은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":4,"concept":"K2-2-u7-C6","difficulty":1,"kind":"mc","stem":"아침 운동장에 가득한 것은?","options":[{"t":"시원한 공기","correct":true},{"t":"뜨거운 바람","mis":"K2-2-u7-X06"},{"t":"자동차 소리","mis":"K2-2-u7-X06"}],"explanation":["시원한 공기예요.","207쪽이에요.","글 ㉯예요."],"asset":{"type":"passage","lines":["㉮ 저는 아침에 다 같이 운동장에서 달리기를 하자는 생각을 전하고 싶어요.","㉯ 첫째, 아침에 운동장을 달리면 기분이 좋아져요.","시원한 아침 공기는 스트레스를 사라지게 해 줘요.","㉰ 둘째, 아침에 운동장을 달리면 더 건강해져요.","점점 체력이 좋아지고 몸무게를 조절하는 데에도 도움이 돼요.","㉱ 며칠 동안만 꾸준히 실천하면 달리는 즐거움에 푹 빠질 거예요."],"title":"『국어』 207쪽 「아침에 운동장을 달려요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#5','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C9',1,'mc','auto','「정말 뿌듯할 것 같습니다.」는 무엇에 해당하나요?',ARRAY['K2-2-u7-X09']::text[],false,'{"seq":5,"concept":"K2-2-u7-C9","difficulty":1,"kind":"mc","stem":"「정말 뿌듯할 것 같습니다.」는 무엇에 해당하나요?","options":[{"t":"느낌","correct":true},{"t":"생각","mis":"K2-2-u7-X09"},{"t":"생각에 대한 까닭","mis":"K2-2-u7-X09"}],"explanation":["느낌이에요.","216쪽이에요.","~할 것 같아요."],"asset":{"type":"passage","lines":["뒤뜰에서 병아리를 키웁시다.","왜냐하면 병아리를 직접 키우면서 책임감을 기를 수 있기 때문입니다.","병아리는 연약해서 잘 보살펴 주어야 한다는 것을 책에서 보았습니다.","우리 반 친구들이 노력해서 병아리를 잘 키운다면 정말 뿌듯할 것 같습니다."],"title":"『국어』 216쪽 규빈이가 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#6','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C8',1,'mc','auto','친구 발표에 말로 보이는 반응으로 알맞은 것은?',ARRAY['K2-2-u7-X01','K2-2-u7-X08']::text[],false,'{"seq":6,"concept":"K2-2-u7-C8","difficulty":1,"kind":"mc","stem":"친구 발표에 말로 보이는 반응으로 알맞은 것은?","options":[{"t":"「좋은 생각인걸?」","correct":true},{"t":"「재미없어.」","mis":"K2-2-u7-X01"},{"t":"「빨리 끝내.」","mis":"K2-2-u7-X08"}],"explanation":["좋은 생각인걸이에요.","지도서 292쪽이에요.","언어 반응이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#7','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C11',1,'mc','auto','봄솔이 글에 바르게 쓴 댓글은?',ARRAY['K2-2-u7-X11','K2-2-u7-X10']::text[],false,'{"seq":7,"concept":"K2-2-u7-C11","difficulty":1,"kind":"mc","stem":"봄솔이 글에 바르게 쓴 댓글은?","options":[{"t":"「나도 같은 생각이야. 복도에서 뛰면 위험하니까.」","correct":true},{"t":"「별로야.」","mis":"K2-2-u7-X11"},{"t":"「너도 맨날 뛰잖아.」","mis":"K2-2-u7-X10"}],"explanation":["까닭과 함께요.","221쪽이에요.","공감해요."],"asset":{"type":"passage","lines":["봄솔이의 글: 쉬는 시간에 복도에서 뛰지 맙시다.","왜냐하면 친구와 부딪쳐 다칠 수 있기 때문입니다.","댓글 ㉠: 좋은 생각이야! 나도 지난주에 복도에서 부딪칠 뻔했어.","댓글 ㉡: 그걸 누가 몰라? 재미없어."],"title":"친구 글과 댓글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#8','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C13',1,'mc','auto','[수피]로 소리 나는 낱말을 바르게 쓴 것은?',ARRAY['K2-2-u7-X15']::text[],false,'{"seq":8,"concept":"K2-2-u7-C13","difficulty":1,"kind":"mc","stem":"[수피]로 소리 나는 낱말을 바르게 쓴 것은?","options":[{"t":"숲이","correct":true},{"t":"수피","mis":"K2-2-u7-X15"},{"t":"숩이","mis":"K2-2-u7-X15"}],"explanation":["숲이예요.","226쪽이에요.","쓰기는 글자대로요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#9','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C5',2,'mc','auto','이 글에서 글쓴이의 생각은?',ARRAY['K2-2-u7-X05']::text[],false,'{"seq":9,"concept":"K2-2-u7-C5","difficulty":2,"kind":"mc","stem":"이 글에서 글쓴이의 생각은?","options":[{"t":"교실에서 다육 식물을 키우자","correct":true},{"t":"다육 식물은 귀엽게 생겼다","mis":"K2-2-u7-X05"},{"t":"예전에 집에서 키웠다","mis":"K2-2-u7-X05"}],"explanation":["키우자예요.","224쪽 예시 답안이에요.","첫 문장이에요."],"asset":{"type":"passage","lines":["우리 교실에서 다육 식물을 키우면 좋겠습니다.","왜냐하면 다육 식물은 키우기가 쉽기 때문이에요.","예전에 집에서 키웠는데 물을 많이 주지 않아도 잘 자랐어요.","다육 식물은 귀엽게 생겨서 교실 분위기를 더 밝게 만들어 줄 거예요."],"title":"『국어』 224쪽 정리하기 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#10','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C12',2,'match','auto','인물과 생각을 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u7-C12","difficulty":2,"kind":"match","stem":"인물과 생각을 이어 보세요.","pairs":[{"l":"규빈","r":"매일매일 병아리를 책임지고 보살필 돌보미를 정하면 돼요."},{"l":"우철","r":"병아리 키워요. 달걀 먹을 수 있잖아요."},{"l":"선생님","r":"병아리를 키우는 것은 좋지만 책임지고 보살필 사람이 필요해요."}],"mis":"K2-2-u7-X06","explanation":["인물마다 달라요.","215쪽이에요.","생각을 이어요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#11','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C7',2,'mc','auto','글쓴이의 생각에 대한 내 생각을 떠올릴 때 도움이 되는 것은?',ARRAY['K2-2-u7-X07']::text[],false,'{"seq":11,"concept":"K2-2-u7-C7","difficulty":2,"kind":"mc","stem":"글쓴이의 생각에 대한 내 생각을 떠올릴 때 도움이 되는 것은?","options":[{"t":"글과 관련한 내 경험이나 알고 있는 것","correct":true},{"t":"친구 생각을 그대로 베끼기","mis":"K2-2-u7-X07"},{"t":"글자 수 세기","mis":"K2-2-u7-X07"}],"explanation":["경험과 아는 것이에요.","209쪽이에요.","생각이 잘 떠올라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#12','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C10',2,'mc','auto','『국어활동』 99쪽 — 자신의 생각을 글로 표현하면 좋은 점은?',ARRAY['K2-2-u7-X07','K2-2-u7-X10']::text[],false,'{"seq":12,"concept":"K2-2-u7-C10","difficulty":2,"kind":"mc","stem":"『국어활동』 99쪽 — 자신의 생각을 글로 표현하면 좋은 점은?","options":[{"t":"내 생각을 정리해서 더 자세히 나타낼 수 있어요","correct":true},{"t":"내 생각만 옳다고 강조할 수 있어요","mis":"K2-2-u7-X07"},{"t":"아무렇게나 빨리 쓸 수 있어요","mis":"K2-2-u7-X10"}],"explanation":["정리하고 자세히요.","국어활동 99쪽이에요.","글의 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#13','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C12',2,'mc','auto','인물이 되어 생각을 말할 때 쓰는 틀은?',ARRAY['K2-2-u7-X07']::text[],false,'{"seq":13,"concept":"K2-2-u7-C12","difficulty":2,"kind":"mc","stem":"인물이 되어 생각을 말할 때 쓰는 틀은?","options":[{"t":"「내가 만약 ~라면……. 그렇게 생각한 까닭은…….」","correct":true},{"t":"「나는 몰라.」","mis":"K2-2-u7-X07"},{"t":"「끝.」","mis":"K2-2-u7-X07"}],"explanation":["만약 ~라면이에요.","222쪽이에요.","까닭과 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#14','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C13',2,'mc','auto','『국어』 225쪽 — ○표 한 문장 아래 글자를 모아 만든 문장은?',ARRAY['K2-2-u7-X13']::text[],false,'{"seq":14,"concept":"K2-2-u7-C13","difficulty":2,"kind":"mc","stem":"『국어』 225쪽 — ○표 한 문장 아래 글자를 모아 만든 문장은?","options":[{"t":"얘들아! 약속을 잘 지키자.","correct":true},{"t":"얘들아! 큼민 지키자.","mis":"K2-2-u7-X13"},{"t":"얘들아! 약속을 잊자.","mis":"K2-2-u7-X13"}],"explanation":["약속을 잘 지키자예요.","225쪽이에요.","생각 문장만 모아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#15','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C2',2,'mc','auto','모둠 활동 규칙을 정할 때 생각을 알맞게 말한 것은?',ARRAY['K2-2-u7-X01','K2-2-u7-X02']::text[],false,'{"seq":15,"concept":"K2-2-u7-C2","difficulty":2,"kind":"mc","stem":"모둠 활동 규칙을 정할 때 생각을 알맞게 말한 것은?","options":[{"t":"「서로의 생각을 존중하기는 어때?」","correct":true},{"t":"「내 말대로 해.」","mis":"K2-2-u7-X01"},{"t":"「아무거나 해.」","mis":"K2-2-u7-X02"}],"explanation":["배려하는 말이에요.","200쪽이에요.","생각과 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#16','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C6',2,'mc','auto','「병아리 키워요. 달걀 먹을 수 있잖아요.」라고 말한 인물은?',ARRAY['K2-2-u7-X06']::text[],false,'{"seq":16,"concept":"K2-2-u7-C6","difficulty":2,"kind":"mc","stem":"「병아리 키워요. 달걀 먹을 수 있잖아요.」라고 말한 인물은?","options":[{"t":"우철","correct":true},{"t":"규빈","mis":"K2-2-u7-X06"},{"t":"선생님","mis":"K2-2-u7-X06"}],"explanation":["우철이에요.","215쪽이에요.","인물과 생각이에요."],"asset":{"type":"passage","lines":["교장 선생님께서 학교 뒤뜰을 자유롭게 꾸며 보라고 하셨어요.","선생님은 꾸미는 건 자유지만 책임도 져야 한다고 하셨어요.","규빈: 병아리를 키우면 닭이 되는 과정도 볼 수 있어요.","우철: 병아리 키워요. 달걀 먹을 수 있잖아요.","선생님: 병아리를 책임지고 보살필 누군가가 필요해요.","규빈: 매일매일 병아리를 책임지고 보살필 돌보미를 정해서 돌볼게요."],"title":"『국어』 211~214쪽 「왜 책임이 필요하죠?」(채화영) 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
