INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#19','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C12',3,'ox','auto','이야기 속 인물이 되어 말할 때는 그렇게 생각한 까닭도 함께 말하는 것이 좋다.',ARRAY['K2-2-u7-X07']::text[],false,'{"seq":19,"concept":"K2-2-u7-C12","difficulty":3,"kind":"ox","stem":"이야기 속 인물이 되어 말할 때는 그렇게 생각한 까닭도 함께 말하는 것이 좋다.","answer":"O","reason_options":[{"t":"까닭을 말하면 듣는 친구가 그 생각을 잘 이해할 수 있어서","correct":true},{"t":"까닭은 몰라도 되니까","mis":"K2-2-u7-X07"}],"mis":"K2-2-u7-X07","explanation":["까닭과 함께요.","222쪽이에요.","생각을 나타내는 방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
