INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#21','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C7',3,'mc','auto','「글쓴이는 ~라고 했어요. 그에 대한 제 생각은 ~예요.」 틀로 발표할 때 꼭 넣으면 좋은 것은?',ARRAY['K2-2-u7-X07','K2-2-u7-X08']::text[],false,'{"seq":21,"concept":"K2-2-u7-C7","difficulty":3,"kind":"mc","stem":"「글쓴이는 ~라고 했어요. 그에 대한 제 생각은 ~예요.」 틀로 발표할 때 꼭 넣으면 좋은 것은?","options":[{"t":"내 생각에 대한 까닭","correct":true},{"t":"글쓴이 이름 세 번","mis":"K2-2-u7-X07"},{"t":"「끝」이라는 말","mis":"K2-2-u7-X08"}],"explanation":["까닭이에요.","210쪽이에요.","생각과 까닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#22','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C11',3,'mc','auto','가장 인상 깊은 댓글을 발표할 때 알맞은 것은?',ARRAY['K2-2-u7-X11']::text[],false,'{"seq":22,"concept":"K2-2-u7-C11","difficulty":3,"kind":"mc","stem":"가장 인상 깊은 댓글을 발표할 때 알맞은 것은?","options":[{"t":"고른 댓글과 그 까닭을 함께 말해요","correct":true},{"t":"「다 별로였어요.」라고 말해요","mis":"K2-2-u7-X11"},{"t":"가장 긴 댓글만 읽어요","mis":"K2-2-u7-X11"}],"explanation":["까닭과 함께요.","221쪽이에요.","발표해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#23','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C11',4,'sa','auto','친구가 쓴 글 아래에 다는 짧은 글을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u7-C11","difficulty":4,"kind":"sa","stem":"친구가 쓴 글 아래에 다는 짧은 글을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["댓글"],"explanation":["댓글이에요.","220쪽이에요.","붙임쪽지에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#24','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C11',4,'essay','teacher','친구가 「급식을 남기지 맙시다.」라는 글을 썼어요. 친구의 마음을 생각하며 댓글을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u7-C11","difficulty":4,"kind":"essay","stem":"친구가 「급식을 남기지 맙시다.」라는 글을 썼어요. 친구의 마음을 생각하며 댓글을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 좋은 생각이야. 음식을 남기면 버려지는 게 아까우니까 나도 먹을 만큼만 받을게.","scoring_points":["친구 생각에 대한 내 생각이에요","까닭이 있어요","고운 말이에요"]},"explanation":["배려하는 댓글이에요.","220쪽이에요.","까닭과 함께요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u7_review_d#25','kor',2,2,'u7','','g2_2_kor_u7_review_d','unit_review','K2-2-u7-C8',4,'essay','teacher','자신의 생각을 친구들 앞에서 발표할 때와 친구의 발표를 들을 때 지킬 태도를 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u7-C8","difficulty":4,"kind":"essay","stem":"자신의 생각을 친구들 앞에서 발표할 때와 친구의 발표를 들을 때 지킬 태도를 하나씩 쓰세요.","answer_guide":{"answer":"예: 발표할 때는 친구들을 바라보며 큰 소리로 또박또박 말한다. 들을 때는 조용히 친구를 바라보며 귀 기울인다.","scoring_points":["발표 태도를 썼어요","듣는 태도를 썼어요"]},"explanation":["둘 다예요.","지도서 309쪽 평가예요.","바른 태도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
